window.GRAPH = {"config": {"title": "Тот, кто остался", "start": "Т-00", "vars": {"ТЕЛ": {"start": 20, "min": 0, "max": 100, "name": "Тело", "tiers": [[0, "хилое"], [20, "обычное"], [40, "крепкое"], [60, "сильное"], [80, "железное"]]}, "РАЗ": {"start": 20, "min": 0, "max": 100, "name": "Разум", "tiers": [[0, "рассеянный"], [20, "обычный"], [40, "цепкий"], [60, "острый"], [80, "блестящий"]]}, "ЭМП": {"start": 20, "min": 0, "max": 100, "name": "Эмпатия", "tiers": [[0, "глухой к людям"], [20, "обычная"], [40, "чуткий"], [60, "тонкий"], [80, "видит насквозь"]]}, "ВОЛ": {"start": 20, "min": 0, "max": 100, "name": "Воля", "tiers": [[0, "робкий"], [20, "обычная"], [40, "упрямый"], [60, "твёрдый"], [80, "несгибаемый"]]}, "ДАР": {"start": 0, "min": 0, "max": 100, "name": "Резонанс", "tiers": [[0, "тишина"], [20, "холодок"], [40, "голоса"], [60, "хор"], [80, "регент"]]}, "ДРЕЙФ": {"start": 0, "min": 0, "max": 100, "name": "Дрейф", "hidden": true}, "СВЯЗЬ_НИКА": {"start": 0, "min": 0, "max": 100, "name": "Ника", "hidden": true}, "СВЯЗЬ_ВИТЬКА": {"start": 20, "min": 0, "max": 100, "name": "Витька", "hidden": true}, "СВЯЗЬ_МАМА": {"start": 40, "min": 0, "max": 100, "name": "Мама", "hidden": true}, "СВЯЗЬ_ОТЕЦ": {"start": 30, "min": 0, "max": 100, "name": "Отец", "hidden": true}, "СВЯЗЬ_ЛУНЁВ": {"start": 0, "min": 0, "max": 100, "name": "Лунёв", "hidden": true, "scope": "В2"}}, "flags": {"F_Т01": {"type": "enum", "values": ["СПОР", "БУБЛИК", "ЧАСЫ", "ДОЛГ"]}, "F_Т02": {"type": "enum", "values": ["ЧЕЙ", "ХОР", "ЛИЦО", "МАМА"]}, "F_Т03": {"type": "enum", "values": ["ШРАМ", "ВОДЯНОЙ", "ЗАМЕТКА", "ВОДОБОЯЗНЬ"]}, "F_Т04": {"type": "enum", "values": ["РЕЛЬСЫ", "РЫНОК", "ЦВЕТМЕТ", "ОЛИМПИАДА"]}, "F_Т05": {"type": "enum", "values": ["ТЕТРАДИ", "ФОТО", "ПРОДАЛ", "СОЖЖЕНО"]}, "F_Т06": {"type": "enum", "values": ["ПЕРЕПЛЫЛ", "ТАЙНА_НИКИ", "ПАЦАНЫ", "БАКЕНЩИК"]}, "F_Т07": {"type": "enum", "values": ["КЛЮЧИ", "ЛЁД", "СДАЛ", "ВИДЕНИЕ"]}, "F_Т08": {"type": "enum", "values": ["ПАЛЫЧ", "ДОМ", "ТОРГ", "ДАТЧИКИ"]}, "F_Т09": {"type": "enum", "values": ["АРМИЯ", "ДОЛГ_СВАРНОМУ", "НИКА", "ДВЕРЬ"]}, "F_ПУТЬ": {"type": "enum", "values": ["ЛАМПА", "ПРОТОКОЛ", "ПАРТИЯ", "БАРАБАН", "ТЁПЛАЯ_ВОДА", "ХОР", "СЕМЬЯ"]}, "F_ЗНАЕТ": {"type": "bool"}, "F_ЗНАЕТ_ДЕДА": {"type": "bool"}, "F_НАПАРНИК_СЕРЁГА": {"type": "bool"}, "F_ГИПОКСИЯ": {"type": "bool"}, "F_В201": {"type": "enum", "values": ["УЧЁБА", "ЖЕЛЕЗО", "КОМПАНИЯ", "ТИШИНА"]}, "F_В204": {"type": "enum", "values": ["УЧЕНИК", "СКЕПТИК", "ОТЕЦ", "МИТЯ"]}, "F_В205": {"type": "enum", "values": ["ПРАВДА", "РАБОТА", "СВИДАНИЕ", "УБРАЛ"]}, "F_В206": {"type": "enum", "values": ["ПОМОГ", "ОТКАЗАЛ", "СДАЛ", "ВРАЧ"]}, "F_В207": {"type": "enum", "values": ["СОГЛАСИЛСЯ", "С_НИКОЙ", "ОТКАЗ"]}, "F_В208": {"type": "enum", "values": ["ЭТАЛОН", "ПРЕРВАЛ"]}, "F_ПРОТОКОЛ": {"type": "bool"}, "F_ЭТАЛОН": {"type": "bool"}}, "meta_entries": [{"id": "сосед-Т07", "scene": "Т-08", "cond": "F_Т07 == ВИДЕНИЕ", "title": "✝ — соседний я", "date": "декабрь 2003", "text": "Лёд у берега, зелёная подсветка приборки под водой. Этот я сел в «девятку» и не вылез. Я видел его глазами одну секунду.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т07"}, "r": {"op": "lit", "v": "ВИДЕНИЕ"}}}], "shock_first": ["Я не сразу понимаю, где я. А когда понимаю, становится только хуже.", "Я только что умер. По-настоящему, до самого конца, и помню это целиком, каждую секунду, как помнят вчерашний день. А стою здесь живой, и вокруг всё в точности как минуту назад, до того, как это случилось.", "Смерть уже ощущается воспоминанием, словно была давно и с кем-то другим, хотя прошла одна секунда. Сны так не болят. Тело помнит всё до последнего вдоха, и руки у меня трясутся.", "Я не понимаю, что со мной происходит. Может, я сошёл с ума. Может, это было предчувствие. Только предчувствие не оставляет во рту вкуса той минуты.", "Одно я знаю точно: туда я больше не хочу."], "shock_again": ["Это случилось снова. Я помню свою смерть так же ясно, как старую фотографию, и стою живой за минуту до неё.", "Легче от того, что это не в первый раз, не становится. Зато теперь я хотя бы знаю, что у меня есть эта минута."], "rollback": [[0, 1], [20, 2], [40, 3], [60, 4], [80, 5]], "seal_groups": {"prologue": "trunk", "trunk": "trunk", "demo": "demo", "branch": "branch", "anchor": "anchor", "final": "final"}, "stihii": ["ВОДА", "ХОЛОД", "ОГОНЬ", "ВОЗДУХ", "ПОРОДА", "ЛЮДИ", "ДОРОГА"], "photo_eras": {"bw": "старое чёрно-белое фото, 1990-е", "color": "цветной глянец из фотомастерской, 2000-е", "digital": "цифровая мыльница, 2010-е", "phone": "смартфон, 2020–2040-е", "future": "слишком чистая картинка будущего, 2050–2061"}}, "scenes": {"В2-01": {"id": "В2-01", "title": "Общага", "date": "сентябрь 2007", "age": 18, "stage": "branch", "photo": "digital", "photo_caption": "Общага на Ленина. Наша 412-я", "photo_prompt": "early digital camera photo from 2007, flash, first-person view of a cramped soviet student dorm room, three iron beds, a poster of a band on the wall, instant noodles on a windowsill, a physics textbook open on the table, a boy in a tracksuit laughing, red-eye, overexposed", "text": [{"md": "Томск встречает меня дождём и пирожками с капустой на вокзале Томск-I, по двенадцать рублей. Я съедаю три, пока ищу нужный автобус, и решаю, что город мне нравится."}, {"md": "Общага на Ленина старая, с лепниной на фасаде и тараканами на кухне. Комендантша смотрит на мой паспорт так, будто я его нарисовал. В 412-й нас трое. Дэн из Северска рассказывает, что у них в городе всё светится, и сам ржёт громче всех. Тагир из Колпашева молча раскладывает по полкам банки с тушёнкой, которые ему дала мама, и ни с кем не делится. Через неделю мы с ним уже едим её вдвоём, и Дэн обижается."}, {"md": "Про звёзды на физфаке первые полгода никто не заикается, тут сплошной матанализ. На первой лекции доцент пишет на доске какой-то интеграл, поворачивается и говорит: «Половина из вас уйдёт после первой сессии. Не обижайтесь, это статистика». Мы ржём, и никто не верит."}, {"md": "На стенде кафедры, между расписанием и объявлением про картошку, висят фотографии преподавателей. Профессор Лунёв В. П. смотрит с карточки усталыми глазами. Я его точно где-то видел и полдня не могу вспомнить где."}, {"md": "Томь здесь та же, что дома, только ниже по течению и шире. По вечерам я хожу на набережную и прикидываю, сколько отсюда плыть до моей заводи. Получается, что нисколько, потому что вода течёт в другую сторону."}], "file": "B2-01.md", "choices": [{"id": "A", "label": "Зубрить: «Демидович», коллоквиумы, первый на семинарах", "fx": [["add", "РАЗ", 10], ["set", "F_В201", "УЧЁБА"]], "outcomes": [{"to": "В2-02"}]}, {"id": "B", "label": "Разгружать вагоны по ночам на Томске-II: деньги и плечи", "fx": [["add", "ТЕЛ", 10], ["set", "F_В201", "ЖЕЛЕЗО"]], "outcomes": [{"to": "В2-02"}]}, {"id": "C", "label": "Жить общагой: гитара, КВН, «Балтика» на подоконнике", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["set", "F_В201", "КОМПАНИЯ"]], "outcomes": [{"to": "В2-02"}]}, {"id": "D", "label": "Ходить ночами на набережную и слушать, что шепчет вода", "fx": [["add", "ДАР", 5], ["add", "РАЗ", 5], ["set", "F_В201", "ТИШИНА"]], "outcomes": [{"to": "В2-02"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 20}}, "visible_src": "ДАР >= 20"}], "after": {"A": [{"md": "Я сижу над «Демидовичем» до двух ночи, а Дэн храпит так, что дрожит стакан на тумбочке. На первом коллоквиуме доцент смотрит в мою зачётку, потом на меня и говорит: «Самохин? Кемеровский? Ну-ну». Первую сессию я сдаю на одни пятёрки, и с этого дня меня зовут списывать все, кому не лень."}], "B": [{"md": "По ночам мы с Тагиром разгружаем вагоны на Томске-II: цемент, сахар, однажды целый вагон бананов. Бригадир платит наличными в конверте и называет нас «студентами» таким голосом, каким обычно ругаются. К Новому году у меня новые кроссовки, плечи шире на размер, и я засыпаю на лекциях по матанализу."}], "C": [{"md": "В общаге я быстро становлюсь своим: гитара, КВН факультета, «Балтика» на подоконнике и разговоры до утра про всё на свете. Сессию я сдаю на тройки, со второго раза. Зато к весне меня знает пол-общаги, и комендантша больше не смотрит на мой паспорт."}], "D": [{"md": "Почти каждую ночь я хожу на набережную. Сижу на парапете над Томью и слушаю, как шуршит вода. Иногда в этом шуршании мне чудится, что кто-то считает, тихо, на два голоса. Я никому про это не говорю и каждый раз возвращаюсь в общагу, когда в окнах уже никого нет."}]}}, "В2-02": {"id": "В2-02", "title": "Грузовой лифт", "date": "9 декабря 2008, 16:40", "age": 19, "stage": "branch", "photo": "digital", "photo_caption": "«Людей не перевозить»", "photo_prompt": "early digital camera photo, dim flickering light inside an old soviet freight elevator, scratched metal walls with a stencil sign forbidding people, a large steel dewar flask of liquid nitrogen with white vapor creeping along the floor, first-person view, noise", "text": [{"md": "Доцент не соврал, после первой сессии от нашего потока осталась половина. Я на втором курсе, удержался и даже подрабатываю лаборантом на кафедре. Мою колбы, таскаю приборы и слушаю, как ругаются аспиранты."}, {"md": "Зоя Михайловна, наша старшая лаборантка, просит поднять из подвала на третий этаж сосуд Дьюара с жидким азотом, литров на сорок. На лестнице ремонт, перила сняты, ступени в цементе. Остаётся грузовой лифт, у которого на дверях по трафарету выведено «ЛЮДЕЙ НЕ ПЕРЕВОЗИТЬ». На эту надпись все плюют, и я тоже."}, {"md": "Между вторым и третьим лифт дёргается и встаёт. Лампочка под потолком мигает и остаётся гореть вполнакала. Крышка сосуда тихо шипит. По полу, вокруг моих кроссовок, ползёт белый туман, как из дым-машины на концерте «Мумий Тролля», только холодный. Я стою, смотрю на него и думаю, что это даже красиво."}], "file": "B2-02.md", "choices": [{"id": "A", "label": "Жать кнопку вызова и ждать диспетчера", "fx": [], "outcomes": [{"to": "✝В2-02.A"}]}, {"id": "B", "label": "Разжать двери и вылезти в щель между этажами", "fx": [], "outcomes": [{"to": "✝В2-02.B"}]}, {"id": "C", "label": "Сосуд шипит всё громче. Открыть крышку, чтобы стравить давление", "fx": [], "outcomes": [{"to": "✝В2-02.C"}]}, {"id": "D", "label": "«Я знаю, что сейчас будет». Залезть повыше, к решётке под потолком, где тёплый воздух, и колотить в стену, пока не услышат", "fx": [["set", "F_ЗНАЕТ", true], ["add", "ДАР", 5]], "outcomes": [{"to": "В2-03"}], "visible": {"op": "or", "a": [{"op": "seen", "id": "✝В2-02.A", "life": true}, {"op": "seen", "id": "✝В2-02.B", "life": true}, {"op": "seen", "id": "✝В2-02.C", "life": true}]}, "visible_src": "seen_life(✝В2-02.A) || seen_life(✝В2-02.B) || seen_life(✝В2-02.C)"}], "after": {"D": [{"md": "Я встаю на поручень, упираюсь макушкой в потолок кабины и прижимаюсь лицом к решётке. Там тепло и пахнет пылью. Свободной рукой я колочу ключом от лаборатории в стенку, ровно, раз в секунду, и не перестаю, даже когда рука немеет."}, {"md": "Через двадцать минут снаружи кричат: «Кто там?!» Лифт открывают ломом. Зоя Михайловна видит туман на полу, бледнеет и сначала ругается, а потом ревёт."}, {"md": "Меня отпаивают чаем на кафедре. Руки трясутся так, что чай я разливаю. Все думают, что от холода."}]}}, "В2-03": {"id": "В2-03", "title": "Лагерный сад", "date": "14 января 2009, 02:30", "age": 19, "stage": "branch", "photo": "digital", "photo_caption": "Старый Новый год у Лёхи на Степановке", "photo_prompt": "early digital camera photo, night, minus forty frost, first-person view of an empty snowy park on a high river bank in Tomsk, orange street lamps in frozen fog, a lonely bench, breath vapor, a dark frozen river far below, noise and blur", "text": [{"md": "После лифта я месяц сплю с включённым светом. Дэн думает, что у меня несчастная любовь, и подсовывает мне диски «Сплина». Я никому ничего не говорю. Не рассказывать же, что я умер в лифте, но как-то не до конца."}, {"md": "На старый Новый год Лёха с нашего потока зовёт всех к себе на Степановку. Родители у него уехали в Колпашево, на восемь человек две бутылки водки и пачка пельменей, которые никто так и не сварил. Водка кончается в два часа ночи, троллейбусы кончились ещё в одиннадцать."}, {"md": "На улице минус сорок два. Воздух звенит, фонари стоят в рыжем тумане. До общаги на Ленина шесть километров, если идти через Лагерный сад, по крутому берегу над Томью. На такси у меня ровно двести рублей, а до стипендии ещё девять дней."}, {"md": "Затылок у меня стынет сильнее, чем щёки на морозе. И на лавочку у памятника в Лагерном саду мне заранее не хочется смотреть, хотя отсюда её даже не видно.", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 20}}}, {"md": "Лена с третьего курса выходит вместе со мной, последней. Живёт она тут же, в соседнем подъезде, но домой не идёт, а стоит и ковыряет варежкой снег на перилах, будто чего-то ждёт."}], "file": "B2-03.md", "choices": [{"id": "A", "label": "Пешком через Лагерный сад. Шесть километров — не крюк", "fx": [], "outcomes": [{"to": "В2-04", "if": {"op": "or", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 40}}, {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т07"}, "r": {"op": "lit", "v": "ЛЁД"}}]}, "if_src": "ТЕЛ >= 40 || F_Т07 == ЛЁД", "fx": [["add", "ТЕЛ", 5]]}, {"to": "✝В2-03.A"}]}, {"id": "B", "label": "Вызвать такси на последние двести рублей", "fx": [["add", "ВОЛ", -5], ["add", "ТЕЛ", -5]], "outcomes": [{"to": "В2-04"}]}, {"id": "C", "label": "Напроситься к Лене переночевать", "fx": [], "outcomes": [{"to": "В2-04", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ЭМП"}, "r": {"op": "num", "v": 35}}, "if_src": "ЭМП >= 35", "fx": [["add", "ЭМП", 5]]}, {"to": "✝В2-03.C"}]}, {"id": "D", "label": "Послушаться холодка в затылке и не идти мимо той лавочки", "fx": [["add", "ДАР", 5], ["add", "ДРЕЙФ", 5]], "outcomes": [{"to": "В2-04"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 20}}, "visible_src": "ДАР >= 20"}], "after": {"A": [{"md": "Я иду быстро и не останавливаюсь ни разу. Мимо лавочки у памятника я прохожу, не глядя на неё, хотя ноги сами просятся сесть. В общагу я попадаю в половине пятого, с белыми щеками и без пальцев на ногах, как мне кажется. Пальцы потом отходят, и это больнее, чем мороз."}], "B": [{"md": "Таксист берёт все двести рублей и ещё ворчит, что в такой мороз меньше чем за триста не ездят. Девять дней до стипендии я ем «Доширак» и занимаю у Тагира тушёнку. Тагир даёт и ничего не говорит, и от этого стыднее."}], "C": [{"md": "— Можно я у тебя пересижу до утра? — говорю я Лене. — А то до Ленина я не дойду."}, {"md": "Лена смеётся и говорит: «Давно бы так». Мы пьём чай у неё на кухне до шести утра, и я впервые с декабря засыпаю без света."}], "D": [{"md": "Я слушаю холодок в затылке и иду не через Лагерный сад, а длинной дорогой по проспекту, где горят окна и ходят редкие машины. Получается на два километра дольше. На лавочку у памятника я так и не смотрю, ни в ту ночь, ни потом."}]}}, "В2-04": {"id": "В2-04", "title": "Я тебя ждал", "date": "апрель 2009", "age": 20, "stage": "branch", "photo": "digital", "photo_caption": "Кафедра. Кабинет 218", "photo_prompt": "early digital camera photo, first-person view of an old professor's office in a Siberian university, stacks of journals, an electric kettle, a chess board mid-game, a faded black-and-white photo of a miner choir on the wall, an open desk drawer, afternoon light through dusty window, noise", "text": [{"md": "В апреле я хожу на открытый семинар кафедры по квантовым измерениям. Второкурсников туда никто не зовёт, но и не выгоняет, и нас там всего шестеро вместе с аспирантами. Ведёт профессор Лунёв, тот самый, с карточки на стенде. Говорит тихо, мел держит как сигарету и постоянно трёт глаза. На втором занятии я наконец вспоминаю, где его видел."}, {"md": "Вторая городская, детское отделение, июль девяносто шестого. Серый костюм, портфель, две пробирки крови. «Что ты там слышал?»"}, {"md": "После семинара он говорит: «Самохин, задержитесь». Мы идём в 218-й. Он закрывает дверь на ключ, ставит чайник, садится и долго смотрит на меня поверх очков."}, {"md": "— Я тебя ждал, — говорит он. — Тринадцать лет."}, {"md": "Под стеклом на его столе лежит пожелтевшая вырезка из «Кузбасса», полколонки про мальчика с Рудничного, который ищет деда в тельняшке. Это моё объявление, я писал его фломастером в семь лет.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т03"}, "r": {"op": "lit", "v": "ЗАМЕТКА"}}}, {"md": "Потом он рассказывает, а чай у меня в кружке остывает нетронутым."}, {"md": "Моего деда звали Тихон Савельевич Самохин. Он был физиком, и Лунёв в восьмидесятых был его аспирантом. С семьдесят третьего года дед вёл закрытую тему под названием «Камертон». Лаборатория была глубоко под землёй, на горизонте минус шестьсот сорок шахты «Глубокая», под Красной Горкой. На той самой «Глубокой», где мой отец двадцать лет рубит уголь и не знает, что у него под ногами."}, {"md": "— Он ставил опыты на себе, — говорит Лунёв. — Сорок один опыт. Сорок первый, в январе восемьдесят шестого, в четыре двенадцать утра, стал последним. Официально записали выброс газа, погибли шесть человек. А то, что он нашёл, он передал твоему отцу, хотел того или нет. А отец передал тебе. В девяносто шестом вода тебя разбудила."}, {"md": "— Что нашёл? — спрашиваю я."}, {"md": "— Ты не умираешь, Андрей. Умирает другой ты, в соседнем мире, где ты выбрал иначе. А память о его смерти достаётся тебе. — Он снимает очки и трёт переносицу. — Скажи, ты ведь уже умирал? Не в девяносто шестом. Недавно."}, {"md": "Я молчу. Он кивает."}, {"md": "— Ты видел его тетради? — вдруг спрашивает он.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}}, {"md": "— Одну фразу запомнил. «Наблюдатель не видит своей смерти. Проверено».", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}}, {"md": "Лунёв долго сидит не шевелясь, а потом начинает смеяться, почти беззвучно, одними плечами, и никак не может перестать.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}}, {"md": "— Ты мне тогда сказал, что они считали, — говорит он. — Я тринадцать лет думаю об этих двух словах.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Он замечает часы у меня на руке. Я ношу их с девяносто шестого, они стоят на четырёх двенадцати, и в общаге надо мной из-за них ржут. Лунёв бледнеет и прижимает ладонь к груди. Потом молча выдвигает ящик стола и кладёт рядом вторые. Те же «Штурманские» со звёздочкой на циферблате, и даже царапина на стекле та же. Только мои потёрты так, будто их носили лет на шестьдесят дольше. Он переворачивает свои, на крышке гравировка «Сверим часы. 12.04.61». Я переворачиваю свои, там то же самое.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ЧАСЫ"}}}, {"md": "— Сверим часы, — говорит Лунёв, и голос у него садится.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ЧАСЫ"}}}, {"md": "Тринадцать лет он меня ждал. Я потом посчитал: ровно столько, сколько я прожил после заводи. Хорошо, что я тогда ещё не знал, чего именно он ждал.", "kind": "old"}], "file": "B2-04.md", "choices": [{"id": "A", "label": "«Учите меня»", "fx": [["add", "ДАР", 10], ["add", "СВЯЗЬ_ОТЕЦ", -10], ["add", "СВЯЗЬ_ЛУНЁВ", 20], ["set", "F_ЗНАЕТ_ДЕДА", true], ["set", "F_В204", "УЧЕНИК"]], "outcomes": [{"to": "В2-05"}]}, {"id": "B", "label": "«Докажите»", "fx": [["add", "РАЗ", 10], ["add", "СВЯЗЬ_ЛУНЁВ", 5], ["set", "F_ЗНАЕТ_ДЕДА", true], ["set", "F_В204", "СКЕПТИК"]], "outcomes": [{"to": "В2-05"}]}, {"id": "C", "label": "Выйти и позвонить отцу", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_ЗНАЕТ_ДЕДА", true], ["set", "F_В204", "ОТЕЦ"]], "outcomes": [{"to": "В2-05"}]}, {"id": "D", "label": "«Это вы стояли у заводи каждый июль?»", "fx": [["add", "ЭМП", 10], ["add", "СВЯЗЬ_ЛУНЁВ", 30], ["set", "F_ЗНАЕТ_ДЕДА", true], ["set", "F_В204", "МИТЯ"]], "outcomes": [{"to": "В2-05"}], "visible": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т06"}, "r": {"op": "lit", "v": "БАКЕНЩИК"}}, "visible_src": "F_Т06 == БАКЕНЩИК"}], "after": {"A": [{"md": "— Учите меня, — говорю я."}, {"md": "Лунёв кивает так, будто другого ответа и не ждал, и пишет мне на листке список книг. Половина на английском, одна от руки, дедовым почерком, ксерокопия. В конце мая я звоню отцу и рассказываю, где теперь провожу вечера. Отец слушает, а потом говорит: «Не лезь туда, Андрюха. Дед полез». И кладёт трубку. До осени мы с ним не разговариваем."}], "B": [{"md": "— Докажите, — говорю я."}, {"md": "Лунёв не обижается. Он достаёт из шкафа старый магнитофон и катушку «Свема», заправляет плёнку и нажимает клавишу. Сквозь треск я слышу дедов голос, которого никогда раньше не слышал: «…сверим часы, четыре двенадцать… глуши…» Дальше шум. Лунёв выключает магнитофон, и руки у него дрожат сильнее моих."}, {"md": "Спорить я после этого перестаю."}], "C": [{"md": "Я выхожу в коридор и звоню отцу с мобильника, на последние деньги. Рассказываю всё, путаясь и перескакивая. Отец долго молчит в трубку, я слышу, как он курит."}, {"md": "— Не лезь туда, Андрюха, — говорит он наконец. — Дед полез."}, {"md": "Первый раз в жизни он сам заговорил о деде. Я возвращаюсь в 218-й, и Лунёв, ни о чём не спрашивая, наливает мне новый чай."}], "D": [{"md": "— Это вы стояли у заводи каждый июль?"}, {"md": "Лунёв снимает очки и долго их протирает."}, {"md": "— Бакенщик рассказал?.. Да. Мой сын, Митя. Восемьдесят восьмой год, девять лет. Ушёл под воду у коряги, тело так и не нашли. Пока тела нет… — Он не договаривает. — Ладно. Пей чай."}, {"md": "С этого дня он говорит со мной иначе, как с тем, кто знает про него что-то, чего не знает никто."}]}}, "В2-05": {"id": "В2-05", "title": "Электроды", "date": "октябрь 2011", "age": 22, "stage": "branch", "photo": "digital", "photo_caption": "Академгородок. ЭЭГ, 128 каналов", "photo_prompt": "early 2010s digital photo, first-person view from a lab chair, a young woman with short hair in a white coat adjusting an EEG electrode cap, wires everywhere, a monitor with brain waves, autumn birch trees and a squirrel in the window, warm lamp light, slight noise", "text": [{"md": "Прошло два с половиной года. Второй год я живу на два города. Всю неделю учусь в Томске, а в среду вечером лезу на верхнюю боковую в ночном поезде на Новосибирск, с чужими носками у самого лица, и оттуда еду в Академгородок. Лунёв договорился с институтом физиологии, и теперь мою голову изучают всерьёз. Каждый четверг меня усаживают в кресло, надевают шапочку на сто двадцать восемь электродов и просят «вспомнить что-нибудь неприятное». Я вспоминаю лифт. На мониторе что-то вспыхивает, и лаборанты переглядываются."}, {"md": "Шапочку мне надевает аспирантка, коротко стриженная, с лицом строгого завуча. Она поправляет электрод у меня за ухом, наклоняется и тихо говорит:"}, {"md": "— Двести пятьдесят две, Самохин. Не дёргайся."}, {"md": "Тут я и узнаю Нику."}, {"md": "Пять лет назад были дача и рассвет, а потом проводы, на которые я не пошёл. После этого мы оба долго делали вид, что ничего не было. Она, похоже, держится до сих пор, только электрод за ухом поправляет дольше, чем надо.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "НИКА"}}}, {"md": "Про темноту под водой знает только она, я рассказал ей на берегу, когда нам было по тринадцать. Выходит, что мы тут меряем, она понимает лучше всех в этой лаборатории.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т06"}, "r": {"op": "lit", "v": "ТАЙНА_НИКИ"}}}, {"md": "Я помню, как мы с Витькой ржали над «новосибирской» на заводи. Она, судя по взгляду, тоже помнит.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т06"}, "r": {"op": "lit", "v": "ПАЦАНЫ"}}}, {"md": "Вечером мы стоим на крыльце института. По берёзам у крыльца скачут белки, наглые, как вахтёрши. Ника курит тонкую сигарету и спрашивает, не глядя на меня:"}, {"md": "— Что они с тобой делают, Андрей? Только честно."}], "file": "B2-05.md", "choices": [{"id": "A", "label": "Рассказать ей всё: лифт, деда, «Камертон»", "fx": [["add", "ЭМП", 5], ["add", "СВЯЗЬ_НИКА", 20], ["set", "F_В205", "ПРАВДА"]], "outcomes": [{"to": "В2-06"}]}, {"id": "B", "label": "«Меряют. Ты же сама меряешь». Держать дистанцию: она аспирантка, я испытуемый", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_НИКА", 5], ["set", "F_В205", "РАБОТА"]], "outcomes": [{"to": "В2-06"}]}, {"id": "C", "label": "«Пошли погуляем, я тебе по дороге всё расскажу». И гулять до ночи", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_НИКА", 15], ["set", "F_В205", "СВИДАНИЕ"]], "outcomes": [{"to": "В2-06"}]}, {"id": "D", "label": "Наутро попросить Лунёва убрать её из проекта: рядом со мной опасно", "fx": [["add", "ВОЛ", 10], ["add", "СВЯЗЬ_НИКА", -10], ["add", "СВЯЗЬ_ЛУНЁВ", 10], ["set", "F_В205", "УБРАЛ"]], "outcomes": [{"to": "В2-06"}]}], "after": {"A": [{"md": "Я рассказываю ей всё, от лифта до дедовой камеры под Красной Горкой. Ника выслушивает до конца и ни разу не перебивает. Сигарета у неё догорает до фильтра, и она не замечает."}, {"md": "— Я так и знала, что ты тогда не просто так вылез, — говорит она наконец."}, {"md": "С этого вечера мы видимся не только по четвергам."}], "B": [{"md": "— Меряют, — говорю я. — Ты же сама меряешь."}, {"md": "Ника кивает, тушит сигарету об урну и уходит в корпус. Дальше всё по-деловому: четверг, шапочка, сто двадцать восемь электродов, «спасибо, Самохин, свободен». Иногда мне кажется, что она хочет что-то спросить, но так и не спрашивает."}], "C": [{"md": "Мы гуляем по Академгородку до трёх ночи, от Морского проспекта до самого Обского моря и обратно. Я рассказываю ей примерно половину, остальное она, похоже, додумывает сама."}, {"md": "У её общаги она говорит: «Ты не изменился, Самохин. Только врать стал лучше». И целует меня в щёку, быстро, как будто ставит печать."}], "D": [{"md": "Утром я захожу к Лунёву и прошу убрать Нику из проекта. Говорю, что рядом со мной опасно, и сам в это верю."}, {"md": "Через неделю её переводят в другую лабораторию. Она узнаёт, кто попросил, и с тех пор кивает мне в коридоре, как соседу по лестничной клетке."}]}}, "В2-06": {"id": "В2-06", "title": "Глеб", "date": "ноябрь 2014", "age": 25, "stage": "branch", "photo": "digital", "photo_caption": "Глеб на семинаре. Последнее фото, где он смеётся", "photo_prompt": "2014 smartphone-era digital photo, first-person view across a seminar table, a thin pale young man of 24 with sharp features laughing at a whiteboard covered in equations, a laptop with a spreadsheet open, fluorescent light, slightly cold tones", "text": [{"md": "Ещё три года проходят в поездах между Томском и Академгородком. Я защищаю диплом, поступаю в аспирантуру к Лунёву и становлюсь самым странным аспирантом кафедры. У Лунёва теперь два «прибора», я и Глеб Ростоцкий."}, {"md": "Глебу двадцать четыре, он из Ленинска-Кузнецкого, худой и острый, как циркуль, и умнее меня раза в три. В девятнадцать лет он попал в аварию на трассе под Юргой. Мать сидела рядом, на пассажирском. Его откачали через шесть минут, её не смогли. Лунёв говорит, что Глебов дед ещё при моём деде попал в какой-то «Реестр везунчиков». Глеб про это слушать не любит."}, {"md": "Хор он слышит, как и я, только обрывками. Жить с этим он придумал по-своему и ищет мир, где мама жива."}, {"md": "В ноябре он показывает мне у себя на ноутбуке таблицу в Excel. Даты, места, отметки «откат 1», «откат 2», всего сорок строк. За каждой строкой стоит соседний мир, где Глеба похоронили."}, {"md": "— Я подбираюсь, — говорит он и улыбается так, что мне хочется отобрать у него ноутбук. — Вчера в Кемерове… ну, в Щегловске… а, ладно. Неважно. Мне надо уходить дальше, Андрей. Ты умеешь дальше. Научи."}, {"md": "Щегловском город, где я родился, называется только в учебнике истории, в тридцать втором году его переименовали."}, {"md": "Глеб не вернулся в марте пятнадцатого. Хор потом сказал мне, что так было во всех мирах, где я его знал. Утешает это слабо.", "kind": "old"}], "file": "B2-06.md", "choices": [{"id": "A", "label": "Учить его слушать Хор", "fx": [["add", "ДАР", 5], ["add", "ДРЕЙФ", 5], ["set", "F_В206", "ПОМОГ"]], "outcomes": [{"to": "В2-07"}]}, {"id": "B", "label": "«Мёртвых не возвращают, Глеб». Отказать", "fx": [["add", "ВОЛ", 5], ["set", "F_В206", "ОТКАЗАЛ"]], "outcomes": [{"to": "В2-07"}]}, {"id": "C", "label": "Рассказать Лунёву про таблицу", "fx": [["add", "РАЗ", 5], ["add", "СВЯЗЬ_ЛУНЁВ", 10], ["set", "F_В206", "СДАЛ"]], "outcomes": [{"to": "В2-07"}]}, {"id": "D", "label": "Отвезти его к врачу, хоть силой", "fx": [["add", "ЭМП", 10], ["set", "F_В206", "ВРАЧ"]], "outcomes": [{"to": "В2-07"}]}], "after": {"A": [{"md": "Я учу его тому, чему научился сам: не гнать голоса, слушать, отличать один от другого. Глеб записывает всё в тетрадь мелким почерком и кивает. Через месяц он говорит, что слышит «ту, что за рулём». Я не спрашиваю, кого он имеет в виду."}], "B": [{"md": "— Мёртвых не возвращают, Глеб, — говорю я. — Ни в каком мире."}, {"md": "Он закрывает ноутбук, вежливо благодарит и уходит. На следующий день здоровается со мной так, будто ничего не было. Это хуже, чем если бы он обиделся."}], "C": [{"md": "Я иду к Лунёву и рассказываю про таблицу. Лунёв в тот же вечер забирает у Глеба ключи от лаборатории и запрещает ему работать до весны."}, {"md": "Глеб узнаёт, кто ему это устроил, и перестаёт со мной разговаривать."}], "D": [{"md": "Я почти силой везу его к психиатру в областную. Глеб не сопротивляется, только смотрит в окно маршрутки и молчит. Врач выписывает ему таблетки. Полгода он их честно пьёт, и полгода мне кажется, что всё обошлось."}]}}, "В2-07": {"id": "В2-07", "title": "Протокол", "date": "март 2016", "age": 27, "stage": "branch", "photo": "digital", "photo_caption": "Лунёв. «Горизонт-640», после откачки", "photo_prompt": "2016 digital photo with flash, deep underground in a coal mine, a small chamber with lead-lined walls covered in frost, an old man in a hard hat and a good coat standing next to a medical cooling bed, chalk marks and numbers on the wall, first-person view, cold blue light", "text": [{"md": "В марте пятнадцатого Глеб не вернулся. Однажды утром он просто не пришёл на семинар, а к обеду позвонили из полиции. Больше я про это говорить не буду."}, {"md": "Я учил его слушать. Каждую ночь, когда не могу уснуть, я вспоминаю, как он кивал и записывал.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В206"}, "r": {"op": "lit", "v": "ПОМОГ"}}}, {"md": "Ключи у него Лунёв забрал, работать запретил. Глеба это не остановило, и Лунёв знает это лучше меня.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В206"}, "r": {"op": "lit", "v": "СДАЛ"}}}, {"md": "Таблетки он бросил за месяц до этого. Мне говорили, что я всё сделал правильно, только легче от этого не стало.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В206"}, "r": {"op": "lit", "v": "ВРАЧ"}}}, {"md": "Весь год без Глеба Лунёв почти не спит. Он поседел до белого и ночует на кафедре, на раскладушке за шкафом."}, {"md": "В марте Лунёв везёт меня в Кемерово. Под Красной Горкой, на «Глубокой», для него вскрывают законсервированный горизонт. Деньги дал какой-то фонд «Сибирский резонанс». Его куратор, вежливый мужик под семьдесят в хорошем пальто, жмёт мне руку и называет меня «молодым человеком с интересной наследственностью». Фамилия у него Шадрин."}, {"md": "Клеть опускается на шестьсот сорок метров. Внизу тепло, как в бане, порода здесь греет, и воду из старого штрека откачивали полгода. Камера деда стоит на подъёме, вода до неё не дошла. Она маленькая, обшитая свинцом, и стены у неё в инее: в углу гудит новая холодильная установка. На стене мелом, почти стёрто, написано «41. 28.01.86. 04:12». На полу стоит медицинская кушетка с охлаждением, ещё в плёнке, а рядом аппарат искусственного кровообращения, похожий на советскую стиральную машину."}, {"md": "— Дед не смог, потому что начал взрослым, — говорит Лунёв. Голос у него ровный, как у человека, который сто раз репетировал. — А по твоему камертону ударили в детстве. Протокол такой. Восемнадцать градусов, двенадцать минут остановки, начинаем в четыре двенадцать. Если получится, ты будешь знать всё, что сейчас только слышишь."}, {"md": "— А если не получится?"}, {"md": "— Тогда ты вернёшься. — Он смотрит на меня поверх очков. — Ты же всегда возвращаешься."}, {"md": "Я знаю, как это делают в больницах: охлаждают часами, через аппарат, с бригадой хирургов. Здесь будут Лунёв, аппарат и я. По всем учебникам так нельзя. Лунёв говорит, что дед учебников не читал, он их писал."}, {"md": "Отец работает в этой же шахте горизонтом выше и не знает, что я здесь, а то бы не пустил."}], "file": "B2-07.md", "choices": [{"id": "A", "label": "Согласиться", "fx": [["add", "ВОЛ", 5], ["set", "F_ПРОТОКОЛ", true], ["set", "F_В207", "СОГЛАСИЛСЯ"]], "outcomes": [{"to": "В2-08"}]}, {"id": "B", "label": "Согласиться, но у монитора будет стоять Ника", "fx": [["add", "ЭМП", 5], ["set", "F_ПРОТОКОЛ", true], ["set", "F_В207", "С_НИКОЙ"]], "outcomes": [{"to": "В2-08"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "СВЯЗЬ_НИКА"}, "r": {"op": "num", "v": 40}}, "visible_src": "СВЯЗЬ_НИКА >= 40"}, {"id": "C", "label": "Отказаться и подняться наверх", "fx": [["add", "ВОЛ", 10], ["add", "СВЯЗЬ_ЛУНЁВ", -20], ["set", "F_В207", "ОТКАЗ"]], "outcomes": [{"to": "В2.2-00"}]}], "after": {"A": [{"md": "— Хорошо, — говорю я."}, {"md": "Лунёв кивает, снимает плёнку с кушетки и назначает дату: четырнадцатое апреля, четыре двенадцать. Месяц я сплю плохо и каждую ночь просыпаюсь ровно тогда, когда надо."}], "B": [{"md": "— Хорошо, — говорю я. — Но у монитора будет Ника."}, {"md": "Лунёв морщится, но соглашается. Ника приезжает из Новосибирска на неделю раньше, полдня молча читает протокол, а потом говорит: «Вы оба больные». И остаётся."}], "C": [{"md": "— Нет, — говорю я и иду к клети."}, {"md": "Лунёв не спорит и даже не оборачивается. Я поднимаюсь наверх один, и всю дорогу, шестьсот сорок метров, слышу, как гудит у него внизу холодильная установка."}]}}, "В2-08": {"id": "В2-08", "title": "Двенадцать минут", "date": "14 апреля 2016, 04:12", "age": 27, "stage": "branch", "photo": "digital", "photo_caption": "Монитор. Минута девятая", "photo_prompt": "2016 digital photo of a medical monitor in a frost-covered underground chamber, flat ECG line, an EEG trace with a strange regular spike pattern, a gloved hand reaching for a switch, cold blue light, first-person view from the bed, blur", "text": [{"md": "Меня охлаждают четыре часа, через аппарат. Холод приходит снизу, от кушетки, и поднимается по позвоночнику, как вода в ванне. Тридцать два градуса, тридцать, двадцать шесть. Лунёв читает цифры вслух ровным голосом диспетчера."}, {"md": "Ника стоит у монитора в куртке поверх халата и держит пальцы у меня на запястье, хотя для этого есть датчики. «Если что-то пойдёт не так, я тебя вытащу, — сказала она наверху. — Мне плевать на протокол».", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В207"}, "r": {"op": "lit", "v": "С_НИКОЙ"}}}, {"md": "На восемнадцати градусах сердце останавливается, как и обещали. На лифт это совсем не похоже. Я просто оказываюсь там же, где был в семь лет, в тёплой тесной темноте."}, {"md": "Только теперь я различаю голоса. Тот, что из лифта, удивлённый. И много незнакомых: кто-то кашляет, как отец после смены, кто-то хрипит по-стариковски. Самый тихий голос детский. Он говорит:"}, {"md": "— Ты живёшь на мои четыре минуты. Помнишь?"}, {"md": "На девятой минуте снаружи, глухо, как через воду, начинает пищать монитор, и пищит он неправильно. Лунёв что-то кричит. Голоса вокруг меня становятся громче и подступают ближе."}, {"md": "Мне вдруг вспоминается фраза из дедовой тетради: «Наблюдатель не видит своей смерти. Проверено». Дед ошибся в одном слове. Видеть наблюдателю ничего и не надо, ему надо слушать.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}}], "file": "B2-08.md", "choices": [{"id": "A", "label": "Остаться до конца и дослушать", "fx": [], "outcomes": [{"to": "В2.1-00", "if": {"op": "and", "a": [{"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В207"}, "r": {"op": "lit", "v": "С_НИКОЙ"}}, {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "СВЯЗЬ_НИКА"}, "r": {"op": "num", "v": 60}}]}, "if_src": "F_В207 == С_НИКОЙ && СВЯЗЬ_НИКА >= 60", "fx": [["add", "ДАР", 20], ["add", "ДРЕЙФ", 10], ["set", "F_ЭТАЛОН", true], ["set", "F_В208", "ЭТАЛОН"]]}, {"to": "В2.1-00", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}, "if_src": "F_Т05 == ТЕТРАДИ", "fx": [["add", "ДАР", 20], ["add", "ДРЕЙФ", 10], ["set", "F_ЭТАЛОН", true], ["set", "F_В208", "ЭТАЛОН"]]}, {"to": "В2.1-00", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 50}}, "if_src": "ТЕЛ >= 50", "fx": [["add", "ДАР", 20], ["add", "ДРЕЙФ", 10], ["set", "F_ЭТАЛОН", true], ["set", "F_В208", "ЭТАЛОН"]]}, {"to": "✝В2-08.A"}]}, {"id": "B", "label": "Рвануться назад, на свет. Лунёв увидит это на энцефалограмме и прервёт сеанс", "fx": [["add", "ДАР", 5], ["set", "F_В208", "ПРЕРВАЛ"]], "outcomes": [{"to": "В2.2-00"}]}, {"id": "C", "label": "Пойти на самый тонкий голос, детский", "fx": [], "outcomes": [{"to": "В2.1-00", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 60}}, "if_src": "ДАР >= 60", "fx": [["add", "ДАР", 20], ["add", "ДРЕЙФ", 10], ["set", "F_ЭТАЛОН", true], ["set", "F_В208", "ЭТАЛОН"]]}, {"to": "✝В2-08.C"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 40}}, "visible_src": "ДАР >= 40"}], "after": {"B": [{"md": "Я разворачиваюсь спиной к голосам и рвусь туда, где снаружи пищит монитор. Это как выныривать с большой глубины, когда воздух кончился ещё на полпути."}, {"md": "Лунёв видит всплеск на энцефалограмме и останавливает протокол. Меня отогревают через аппарат два часа. Сердце запускается с третьего разряда."}]}}, "В2.1-00": {"id": "В2.1-00", "title": "Эталон", "date": "апрель 2016", "age": 27, "stage": "branch", "photo": "phone", "photo_caption": "Первое утро после", "photo_prompt": "2016 smartphone photo, dawn over a coal mine headframe in Kemerovo, snow melting, a hand with a fresh hospital bracelet holding a paper cup of tea, everything looks unusually sharp and clean, first-person view", "text": [{"md": "Аппарат отогревает меня, и сердце запускается на одиннадцатой минуте, с первого разряда. Я открываю глаза и знаю, что сейчас Лунёв уронит очки, и он их роняет. Знаю, что через четыре секунды мигнёт лампочка над дверью. Через четыре секунды она мигает."}, {"md": "Хор теперь говорит внятно и по очереди, и я различаю каждого, как одноклассников на перекличке."}, {"md": "Ника сидит на полу камеры, прислонившись к свинцовой стене, и плачет, не вытирая лица. Потом говорит: «Ты был мёртвый одиннадцать минут, Самохин. Я считала».", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В207"}, "r": {"op": "lit", "v": "С_НИКОЙ"}}}, {"md": "Наверху, у клети, меня ждёт Шадрин. Он берёт мою ладонь в обе свои, как депутат на встрече с избирателями, и говорит, что с этого дня у меня будет очень интересная жизнь."}, {"md": "Здесь начинается подветвь В2.1 «Удача»: закрытый институт под Москвой, «оракул катастроф», растущий Дрейф. Она ещё пишется.", "kind": "sys"}], "file": "B2-1-00.md"}, "В2.2-00": {"id": "В2.2-00", "title": "Отказ", "date": "апрель 2016", "age": 27, "stage": "branch", "photo": "phone", "photo_caption": "Кафедра, ключ на гвоздике", "photo_prompt": "2016 smartphone photo, an empty professor's office at night, an open drawer with one pair of old soviet watches, a chess board, a cold electric kettle, first-person view, dim yellow light", "text": [{"md": "После сеанса Лунёв не говорит со мной три дня. На четвёртый приходит с бутылкой коньяка, наливает две рюмки и не пьёт свою.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В208"}, "r": {"op": "lit", "v": "ПРЕРВАЛ"}}}, {"md": "Лунёв не звонит мне две недели. Я тоже не звоню.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_В207"}, "r": {"op": "lit", "v": "ОТКАЗ"}}}, {"md": "Через две недели, в шестом часу утра, мне звонит дежурный с «Глубокой». Профессор Лунёв спустился на горизонт один, по пропуску фонда, и с четырёх двенадцати не выходит на связь. Что я там найду, я знаю ещё до того, как сажусь в такси."}, {"md": "Я нахожу его в камере деда. Кушетка холодная, монитор выключен. На стене мелом, рядом со стёртым «41», свежее: «42»."}, {"md": "Здесь начинается подветвь В2.2 «Отказ»: учитель физики в кемеровской школе, возможно, семья с Никой, и в 2040-х девочка Даша, которая слышит голоса. Она ещё пишется.", "kind": "sys"}], "file": "B2-2-00.md"}, "Д-00": {"id": "Д-00", "title": "Демо. «Глубокая»", "date": "осень 2009", "age": 20, "stage": "demo", "photo": "color", "photo_caption": "«Глубокая», АБК. 2009", "photo_prompt": "glossy color photo print from 2009 with orange date stamp in the corner, first-person view, a soviet-era coal mine administrative building in Kemerovo, grey sky, miners in orange helmets smoking near the entrance, slightly faded colors", "text": [{"md": "Это демо механики смерти и отката, а не канон. Настоящая ветвь «Лампа» будет написана позже.", "kind": "sys"}, {"md": "Мне двадцать. Я хожу в забой на «Глубокую», в одну смену с батей. Каждое утро ламповщица Таня выдаёт мне лампу и самоспасатель и говорит одно и то же: «Принёс обратно — молодец». Я каждый раз отвечаю: «А если не принесу?» — и каждый раз получаю журналом выдачи по каске."}, {"md": "Про девяносто шестой я почти не вспоминаю. Иногда только просыпаюсь ровно в четыре двенадцать и лежу, слушаю, как отец за стенкой курит на балконе. Он тоже встаёт в это время. Мы про это не разговариваем, у Самохиных вообще не принято разговаривать."}, {"md": "За два года в забое человек меняется. Каким стал я?"}], "file": "D-00.md", "choices": [{"id": "A", "label": "Здоровым, как лось: турник во дворе, отбойник в забое, по выходным на разгрузку вагонов", "fx": [["add", "ТЕЛ", 30]], "outcomes": [{"to": "Д-01"}]}, {"id": "B", "label": "Головастым: заочка в горном, конспекты в бытовке, все инструкции наизусть", "fx": [["add", "РАЗ", 25], ["add", "ТЕЛ", 5]], "outcomes": [{"to": "Д-01"}]}, {"id": "C", "label": "Странным: ночами сижу на берегу заводи и слушаю, как она молчит", "fx": [["add", "ДАР", 30]], "outcomes": [{"to": "Д-01"}]}]}, "Д-01": {"id": "Д-01", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stage": "demo", "photo": "color", "photo_caption": "(кадр не сохранился)", "photo_prompt": "glossy color photo print with orange date stamp, first-person view, coal face in a mine lit by a single headlamp, black glittering coal wall, a gloved hand on a pneumatic pick, coal dust in the air, dark, slightly blurred", "text": [{"md": "Забой гудит, как пустая бочка. Я долблю пласт, Михалыч за спиной кидает уголь на конвейер и в третий раз за смену рассказывает анекдот про тёщу и парашют. Смеюсь я тоже в третий раз, из уважения к стажу."}, {"md": "Потом пласт вздыхает. Звука нет, просто стена передо мной делает вдох. Лампа выхватывает трещину, и трещина бежит вверх быстрее, чем я успеваю поднять за ней голову. Михалыч замолкает на полуслове. Впереди в темноте начинает шуршать, ровно и мощно, как песок в огромных часах."}, {"md": "— Выброс, — говорит Михалыч тихо и очень спокойно."}, {"md": "От этого спокойствия у меня отнимаются ноги."}], "file": "D-01.md", "choices": [{"id": "A", "label": "Бежать назад по штреку", "fx": [], "outcomes": [{"to": "✝Д-01.A"}]}, {"id": "B", "label": "Упасть на почву, закрыть голову руками", "fx": [], "outcomes": [{"to": "✝Д-01.B"}]}, {"id": "C", "label": "Вцепиться в стойку крепи и держаться", "fx": [], "outcomes": [{"to": "✝Д-01.C"}]}, {"id": "D", "label": "«Я это уже видел». Не к выходу, а в нишу за трансформатором, и тащить Михалыча за собой", "fx": [["set", "F_ЗНАЕТ", true], ["add", "ДАР", 5]], "outcomes": [{"to": "Д-02"}], "visible": {"op": "or", "a": [{"op": "seen", "id": "✝Д-01.A", "life": true}, {"op": "seen", "id": "✝Д-01.B", "life": true}, {"op": "seen", "id": "✝Д-01.C", "life": true}]}, "visible_src": "seen_life(✝Д-01.A) || seen_life(✝Д-01.B) || seen_life(✝Д-01.C)"}], "after": {"D": [{"md": "Я хватаю Михалыча за ворот и тащу в нишу за трансформатором. Он упирается и матерится, пока за нашими спинами не начинает реветь. Уголь течёт мимо, как чёрная река, и останавливается в метре от наших сапог."}, {"md": "Мы сидим в нише, пока нас не откапывают. Михалыч молчит, а потом спрашивает тихо: «Ты откуда знал?» Я не отвечаю. Я и сам не знаю, как это сказать."}]}}, "Д-02": {"id": "Д-02", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stage": "demo", "photo": "digital", "photo_caption": "Штрек. Снято на телефон, которым нельзя снимать в шахте", "photo_prompt": "early 2010s digital point-and-shoot photo, noisy, first-person view, a long dark coal mine drift with rails, a single headlamp beam, a gas detector on a belt glowing red, far behind a second miner's lamp, high ISO noise", "text": [{"md": "Два с лишним года я никому про это не рассказывал. Михалыч тоже молчит. Тогда, в ноябре, я за секунду до выброса затащил его в нишу за трансформатором, и теперь он смотрит на меня, как на икону, в которую не очень верит. На Пасху принёс мне кулич, положил на стол в бытовке и долго не уходил."}, {"md": "Умереть у меня, оказывается, не получается. Получается только запомнить, как умирал, и ходить с этим на смену."}, {"md": "Датчик на поясе начинает пищать, и я понимаю, что это не глюк, ещё до того, как гаснет свет. Вентиляция встала, в лаве становится очень тихо. Метрах в сорока сзади матерится Серёга, фонарь у него мечется по стенам."}, {"md": "Метан не пахнет. Это первое, что говорят на курсах, и единственное, что я сейчас помню. До ствола восемьсот метров по главному штреку. Справа старая сбойка, наполовину заваленная породой."}, {"md": "В затылке холодеет, будто сзади кто-то стоит и дышит мне в шею. Кто-то, кто уже стоял на этом месте и дальше не пошёл.", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 20}}}], "file": "D-02.md", "choices": [{"id": "A", "label": "Бежать к стволу по главному штреку", "fx": [], "outcomes": [{"to": "Д-03", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 45}}, "if_src": "ТЕЛ >= 45", "fx": [["add", "ТЕЛ", 5]]}, {"to": "✝Д-02.A"}]}, {"id": "B", "label": "Включить самоспасатель, уйти в сбойку и ждать", "fx": [], "outcomes": [{"to": "Д-03", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "РАЗ"}, "r": {"op": "num", "v": 40}}, "if_src": "РАЗ >= 40", "fx": [["add", "РАЗ", 5]]}, {"to": "✝Д-02.B"}]}, {"id": "C", "label": "Вернуться за Серёгой", "fx": [], "outcomes": [{"to": "Д-03", "if": {"op": "and", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 45}}, {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ЭМП"}, "r": {"op": "num", "v": 25}}]}, "if_src": "ТЕЛ >= 45 && ЭМП >= 25", "fx": [["add", "ЭМП", 5]]}, {"to": "✝Д-02.C"}]}, {"id": "D", "label": "Прислушаться к тому, кто дышит в затылок", "fx": [["add", "ДАР", 5], ["add", "ДРЕЙФ", 5]], "outcomes": [{"to": "Д-03"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 25}}, "visible_src": "ДАР >= 25"}, {"id": "E", "label": "Лечь на почву, натянуть мокрую куртку на лицо и ждать", "fx": [["add", "ТЕЛ", -10], ["set", "F_ГИПОКСИЯ", true]], "outcomes": [{"to": "Д-03"}]}]}, "Д-03": {"id": "Д-03", "title": "Конец демо", "date": "3 марта 2012", "age": 23, "stage": "demo", "photo": "digital", "photo_caption": "На-гора", "photo_prompt": "early 2010s digital photo, first-person view, grey dawn sky over coal mine headframe, snow, miners' faces black with coal dust, steam from breath", "text": [{"md": "Нас поднимают через шесть часов. Голова гудит, как трансформатор, пальцы не слушаются, и меня два раза выворачивает прямо в клети. Врач в медпункте светит фонариком в глаза и говорит: «Гипоксия, жить будешь». Я киваю. Про «жить буду» он даже не представляет, насколько прав.", "if": {"op": "truthy", "n": "F_ГИПОКСИЯ"}}, {"md": "На-гора уже светло, снег на копре розовый от рассвета. Серёга сидит на лавке у АБК, курит, хотя курить ему сейчас нельзя ни при каких обстоятельствах, и мелко смеётся без остановки.", "if": {"op": "not", "a": {"op": "truthy", "n": "F_ГИПОКСИЯ"}}}, {"md": "Таня-ламповщица забирает у меня лампу и держит её в руках дольше обычного."}, {"md": "— Принёс обратно, — говорит она. — Молодец."}, {"md": "Я не говорю ей, что в каком-то другом мире она сейчас стоит у стойки с лампами и смотрит на пустой крючок с моим номером. Я и сам не знаю, откуда это знаю."}, {"md": "Конец демо. Загляни в «Хор»: там все, кем ты успел побыть. Потом начни новую жизнь и попробуй умереть иначе.", "kind": "sys"}], "file": "D-03.md"}, "Ж-00": {"id": "Ж-00", "title": "Эта жизнь ещё пишется", "date": "2007", "age": 18, "stage": "demo", "photo": "digital", "photo_caption": "(плёнка не проявлена)", "photo_prompt": "early digital camera photo, almost black, a blurry silhouette walking away along railway tracks at dawn, heavy noise", "text": [{"md": "Горная Шория, Мрассу, энцефалитные клещи и звёзды, каких в городе не бывает. Пацан, который утонул в Томи, уходит долбить камень, и вода ему там нужна только в котелке.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ПАРТИЯ"}}}, {"md": "Копанки под Киселёвском, долги, подпольный клуб в Новокузнецке и игра под названием «Барабан». Там я пойму, что смерть можно продавать. Так себе открытие.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "БАРАБАН"}}}, {"md": "Новосибирск, потом Паттайя, потом море, где вода тёплая. Я буду учить людей дышать под водой. О деде не узнаю никогда.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ТЁПЛАЯ_ВОДА"}}}, {"md": "Областная психиатрическая, Алтай, скит на верхней Мрассу. Голоса у меня в голове говорят правду, и от этого не легче.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "«Азот», ипотека, «Гранта», дача в Ягуновском, дочка. Самая обычная жизнь, и в ней страшнее всего.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "СЕМЬЯ"}}}, {"md": "Эта жизнь ещё пишется. Сейчас готово демо механики смерти и отката: жизнь шахтёра на «Глубокой». Можно пройти его, а можно начать новую жизнь через меню «Я».", "kind": "sys"}], "file": "J-00.md", "choices": [{"id": "A", "label": "Пройти демо: «Глубокая», 2009", "fx": [], "outcomes": [{"to": "Д-00"}]}]}, "Т-00": {"id": "Т-00", "title": "Пролог. Сухое русло", "date": "28 июля 2061, 03:42", "age": 72, "stage": "prologue", "photo": "future", "photo_caption": "Русло Томи. 2061", "photo_prompt": "first-person view, night, dry stone riverbed of a wide Siberian river, a perfectly round black pond full to the brim in the middle, a white bleached snag sticking out of the water like a hand, a bright comet with a long tail above, hyper-clean ultra-sharp image, unnaturally perfect, no people", "text": [{"md": "Томь ушла третьим летом подряд. Там, где в девяносто шестом я боялся заплывать за буйки, теперь ходят пешком. Камни, ржавая «копейка» вверх колёсами, пыль белая, как мука из гуманитарки. От Кемерова до самого Томска русло сухое, и по фарватеру гуляют с собаками."}, {"md": "А заводь стоит. Круглая, метров сорок поперёк, полная до краёв и чёрная. Учёные из Томска три лета гоняли по ней сонары и в отчёте написали, что дна нет. Могли бы сэкономить грант и спросить меня. Дно есть, я на нём лежал."}, {"md": "Над руслом висит комета. Хвост лёг точно вдоль реки, хоть по нему сверяй направление. В одиннадцатом классе астрономичка пообещала нам эту комету: «Вам будет по семьдесят два. Доживёте — посмотрите». Я дожил, Галина Ивановна, сижу вот на камне и смотрю."}, {"md": "Сколько раз я умирал, честно не помню. Это у них надо спрашивать, они помнят всё. Перед рассветом их почти не слышно, только шуршат, как бабкин «Рекорд» после конца эфира."}, {"md": "Коряга торчит на прежнем месте, белая и гладкая, растопыренная, как пятерня. Шестьдесят пять лет назад я за неё не удержался."}, {"md": "Сейчас без восемнадцати четыре, и до рассвета есть время рассказать всё по порядку, с того июля, когда мне было семь и я ещё ни разу не умирал."}], "file": "T-00.md", "next": "Т-01"}, "Т-01": {"id": "Т-01", "title": "Чёрная заводь", "date": "28 июля 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "Витька, Ника и Бублик. Лето 96-го", "photo_prompt": "old black-and-white family photo, 1996, first-person view from a 7-year-old, river bank with flat slate stones, a freckled boy of 8 pulling off his t-shirt, a serious girl of 7 in a panama hat holding a ginger puppy, dark still water behind, a white snag like a hand in the distance, grain, scratches, white border", "text": [{"md": "Летом девяносто шестого во дворе пахнет гудроном и тополиным пухом, а ещё углём, потому что углём у нас пахнет всё. Даже у мамы волосы пахнут углём, когда она приходит со смены с обогатительной. Мне семь лет. У меня есть полвелика (это «Кама» без одной педали, вторая половина Витькина), вкладыш от «Турбо» с красной «Ламборгини» и ещё целый август."}, {"md": "На Чёрную заводь ходить нельзя. Бабка с первого этажа говорит, что там в восемьдесят каком-то утонул пацан с Шахтёрской и его так и не нашли, потому что там сваи и водяной. Витька говорит, что водяного не бывает, а сваи бывают, и они засасывают. Поэтому мы ходим именно туда."}, {"md": "Нас трое. Витька на год старше, рыжий в крапинку, орёт громче всех во дворе и врёт, что плавает как дельфин. Дельфинов он видел по телеку. Ника — его двоюродная сестра из Новосибирска, её привезли к нам на всё лето «подышать». Мама говорит, что у нас дышать нечем, одна пыль с химией, но Нике нравится. У неё панамка с вишнями, лицо серьёзное, как у завуча, и рыжий щенок Бублик, который пока не знает слова «нельзя»."}, {"md": "Вода в заводи чёрная, как чай, который папа пьёт после смены, и дна не видно даже у самого берега. С дальнего края торчит белая коряга с растопыренными сучьями, вылитая рука. Солнце лупит прямо в глаза. Я щурюсь и вижу, что под водой у коряги что-то блестит и подмигивает, причём мне, а Витьке нет."}, {"md": "— Слабо до коряги? — Витька стаскивает футболку через голову и застревает в ней. — Кто не доплывёт, тот девчонка."}, {"md": "— Я девчонка, — говорит Ника. — И я не дура туда плыть."}, {"md": "Витька вылезает из футболки красный и, чтобы хоть кого-то победить, швыряет в воду палку. Бублик с визгом летит за ней прямо с камня. Его сразу разворачивает и тащит к коряге, над водой торчат одни уши. Ника кричит так, что с того берега взлетают вороны."}, {"md": "Бабка с первого этажа насчёт этой заводи была права. Почти во всех мирах, где я тогда полез в воду, меня потом так и не нашли.", "kind": "old"}, {"md": "Надо что-то делать прямо сейчас, пока Бублика не утащило."}], "file": "T-01.md", "choices": [{"id": "A", "label": "«Мне не слабо!» — плыть с Витькой наперегонки к коряге", "fx": [["add", "ВОЛ", 10], ["add", "ТЕЛ", 5], ["add", "ЭМП", -5], ["set", "F_Т01", "СПОР"]], "outcomes": [{"to": "Т-02"}]}, {"id": "B", "label": "Прыгнуть за Бубликом", "fx": [["add", "ЭМП", 10], ["add", "ВОЛ", 5], ["add", "РАЗ", -5], ["add", "СВЯЗЬ_НИКА", 10], ["set", "F_Т01", "БУБЛИК"]], "outcomes": [{"to": "Т-02"}]}, {"id": "C", "label": "Нырнуть к тому, что блестит у коряги", "fx": [["add", "РАЗ", 10], ["add", "ДАР", 5], ["add", "ВОЛ", -5], ["set", "F_Т01", "ЧАСЫ"]], "outcomes": [{"to": "Т-02"}]}, {"id": "D", "label": "Бежать за взрослыми", "fx": [["add", "РАЗ", 5], ["add", "ЭМП", 5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т01", "ДОЛГ"]], "outcomes": [{"to": "Т-02"}]}]}, "Т-02": {"id": "Т-02", "title": "Четыре минуты", "date": "28 июля 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "(кадр засвечен)", "photo_prompt": "completely black frame of an old black-and-white photo, only faint light rays from above as if seen from deep under water, grain, a single tiny glint, white border, scratched", "text": [{"md": "На середине я обгоняю Витьку, первый раз в жизни, и даже успеваю обрадоваться. У свай вода становится тяжёлой, как мокрое одеяло, и кто-то спокойно, по-хозяйски берёт меня за ноги и тянет вниз. Последнее, что я вижу сверху, это Витькины пятки. Витька гребёт к берегу.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "СПОР"}}}, {"md": "Бублик визжит и лупит лапами по воде. Я хватаю его за шкирку и толкаю к берегу изо всех сил, как мяч. Он выкарабкивается на камень и отряхивается прямо на Нику. А меня течение крутит, как щепку, и укладывает под корягу.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "Блестяшка под водой оказывается ближе, чем казалось. Я тянусь, хватаю что-то холодное и тяжёлое на железном браслете и сжимаю кулак. И тут коряга цепляет меня за шорты, и наверх я уже не могу.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ЧАСЫ"}}}, {"md": "Я успеваю пробежать по берегу шагов двадцать, и тут Ника кричит не своим голосом. Витька-дельфин полез за щенком и колотит руками у коряги, а голова у него уходит под воду. Как я оказался в воде, я не помню. Помню, как толкаю Витьку снизу в мокрую спину, а он хватается за корягу и лезет вверх прямо по мне, по голове, как по лестнице.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ДОЛГ"}}}, {"md": "Коряга режет мне ладонь, длинно, от большого пальца до запястья. Я чувствую это даже сквозь холод. Потом холод куда-то девается."}, {"md": "Под водой темно и тепло, и я тут не один. Никого не видно, но их много. Это как в автобусе утром, когда глаза закроешь, а всё равно знаешь, что кругом люди и все толкаются."}, {"md": "Сверху кто-то считает вслух тонким девчачьим голосом, сбивается и начинает снова."}, {"md": "Врачи потом говорили маме про переохлаждение и нырятельный рефлекс. Умные слова. Никаких рефлексов я под водой не помню. Помню, что было тесно.", "kind": "old"}, {"md": "Мне не страшно, честно. Только надо решить, что тут делать."}], "file": "T-02.md", "choices": [{"id": "A", "label": "Плыть на голос", "fx": [["add", "ВОЛ", 10], ["set", "F_Т02", "ЧЕЙ"]], "outcomes": [{"to": "Т-02б"}]}, {"id": "B", "label": "Слушать, что они шепчут", "fx": [["add", "ДАР", 10], ["set", "F_Т02", "ХОР"]], "outcomes": [{"to": "Т-02б"}]}, {"id": "C", "label": "Посмотреть вниз", "fx": [["add", "РАЗ", 10], ["set", "F_Т02", "ЛИЦО"]], "outcomes": [{"to": "Т-02б"}]}, {"id": "D", "label": "Позвать маму", "fx": [["add", "ЭМП", 10], ["add", "СВЯЗЬ_МАМА", 5], ["set", "F_Т02", "МАМА"]], "outcomes": [{"to": "Т-02б"}]}]}, "Т-02б": {"id": "Т-02б", "title": "Двести пятьдесят две", "date": "28 июля 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "Вторая городская, детское. Июль 1996", "photo_prompt": "old black-and-white photo, 1996, first-person view from a hospital bed, a soviet hospital ward with tall window and peeling paint, a woman's hand holding a child's bandaged hand, grain, white border", "text": [{"md": "Голос в темноте детский и дворовый.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "— Ты чей?", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "— Самохин, — говорю я, хотя рта у меня тут нет.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "— Ну так и вали к своим, — говорит голос и толкает меня в грудь. Больно, как мячом под дых.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "Я слушаю. Шёпот распадается на голоса, и все они говорят моим голосом, только один тоньше, другой ниже, а третий хрипит, как папа после смены. Они считают вместе с девчонкой сверху: сто девяносто, сто девяносто один. Им очень надо не сбиться.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Я смотрю вниз и вижу себя. Я лежу на песке белый, как та коряга, а надо мной на коленях стоит дед в мокрой тельняшке и давит мне на грудь двумя руками. Лицо у него как у папы, только старое и небритое. Он вытирает глаза ладонью, и на ладони у него шрам от большого пальца до запястья. Точно такой, какой мне только что сделала коряга.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЛИЦО"}}}, {"md": "Я зову маму, и темнота пахнет углём, мамиными волосами после смены. Кто-то кладёт мне на лоб большую шершавую ладонь. Она не мамина, но я всё равно не боюсь.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "МАМА"}}}, {"md": "Потом мне в грудь бьёт, как лошадь копытом, и я кашляю. Изо рта выливается полреки. Песок на зубах, солнце, небо слишком яркое. Кто-то поворачивает меня на бок, а вода всё идёт и идёт."}, {"md": "Когда я начинаю видеть, того, кто меня откачивал, уже нет. Ноги мне кто-то накрыл мокрой брезентовой штормовкой, а к тальнику идут следы босых ног, длинные, взрослые. Кусты ещё качаются."}, {"md": "Ника сидит рядом на корточках, губы синие, панамка в кулаке, и смотрит на меня как на чужого."}, {"md": "— Двести пятьдесят две, — говорит она. — Я считала. Двести пятьдесят две секунды."}, {"md": "Я разжимаю кулак. Поверх свежего пореза лежат мужские часы на железном браслете, мокрые, со звёздочкой на циферблате. Стрелки стоят на четыре двенадцать. Витька лезет посмотреть, и я, сам не знаю почему, опять сжимаю кулак.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ЧАСЫ"}}}, {"md": "Витька стоит по колено в воде и трясётся весь, от макушки до пяток. Не ревёт, Витька никогда не ревёт. Потом говорит: «Ты чё, дурак?» — и садится прямо в воду.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ДОЛГ"}}}, {"md": "Витька стоит в стороне и на меня не смотрит вообще, как будто если не смотреть, то ничего и не было.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "СПОР"}}}, {"md": "Мокрый Бублик, тощий, как крыса, лезет мне в лицо и вылизывает песок со щёк. Ника его не оттаскивает.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "Через полчаса приезжает скорая, «буханка» с красным крестом и без одной фары. Мама влетает в неё прямо в рабочей робе, бьёт меня по щеке и тут же обнимает так, что я опять не могу дышать. В больнице мне зашивают ладонь, четыре шва. Врач в коридоре говорит маме «переохлаждение» и «повезло». Про деда в тельняшке милиция до вечера спрашивает у всего Рудничного. Такого никто не знает."}, {"md": "На другой день в палату приходит ещё один врач, не наш. Он в сером костюме, без халата, с портфелем, говорит, что из Томска, «по обмену опытом». Говорит он тихо и всё время трёт глаза. Он берёт у меня кровь, две пробирки, хотя утром уже брали и медсестра Зина ругалась, что у меня вены как ниточки. Потом наклоняется совсем близко, чтобы Зина не слышала, и спрашивает:"}, {"md": "— Что ты там слышал?"}, {"md": "Я говорю, что они считали. Он сразу садится ко мне на кровать, хотя на кровать садиться нельзя, Зина за это гоняет. Сидит, весь белый. Я думаю, может, ему тоже будут ладонь зашивать.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Я не знаю, что сказать, и пожимаю плечами. Он кивает, как будто я всё-таки ответил, треплет меня по голове и уходит. Пробирки он кладёт в портфель.", "if": {"op": "cmp", "c": "!=", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Сорок лет было этому «доктору». Выглядел на все шестьдесят. В девяносто шестом все так выглядели.", "kind": "old"}, {"md": "Мне семь лет, я утонул и вылез обратно. А откуда именно вылез, пойму очень не сразу."}], "file": "T-02b.md", "next": "Т-03"}, "Т-03": {"id": "Т-03", "title": "Водяной", "date": "сентябрь 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "1 «А», школа № 41. 1 сентября 1996", "photo_prompt": "old black-and-white school photo, September 1996, first-person view from a 7-year-old holding gladioli, a fresh pink scar across the palm, a crowd of first-graders in front of a soviet brick school, mothers in perms, grain, white border", "text": [{"md": "Первого сентября я иду в первый класс с гладиолусами и розовым шрамом поперёк ладони. Гладиолусы мама выменяла у соседки на банку смородинового варенья, а шрам мне достался бесплатно, вместе с четырьмя швами, которые сняли ещё в августе."}, {"md": "На второй день меня уже зовут Водяным. Про то, как Самохин-младший утонул и не утонул, на Рудничном болтают больше, чем про «Санта-Барбару», и знает даже буфетчица тётя Люба. Она даёт мне лишнюю булочку с повидлом, как больному."}, {"md": "В субботу из частного сектора под Красной Горкой приезжает бабушка. Привозит банку груздей и забирает с балкона штормовку, в которой меня принесли. Мама её постирала, а выкинуть так и не решилась. Бабушка долго держит штормовку на коленях и просит рассказать про деда, который меня вытащил. Сам я его толком не видел, поэтому пересказываю за Никой, что он старый, в тельняшке и лицом похож на папу."}, {"md": "— Тиша?.. — говорит бабушка очень тихо, и говорит не мне."}, {"md": "Тишей звали моего деда. Он умер, когда меня ещё не было, «на шахте». У нас в Кемерове про всех дедов так говорят. Мама уводит бабушку на кухню, и они там долго гремят чашками, хотя чай никто не наливает."}, {"md": "Вечером за ужином отец рассказывает про девяносто первый год, когда он с похмелья проспал смену, а клеть в тот день оборвалась."}, {"md": "— Мы, Самохины, везучие, — говорит он и стучит костяшками по столу."}, {"md": "— Пап, а ты чей? — спрашиваю я, сам не знаю зачем.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "Отец роняет кружку. Чай разливается по клеёнке, мама ругается и бежит за тряпкой, а отец сидит и смотрит на меня, пока она вытирает. Мне никто ничего не объясняет.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "Клеть в девяносто первом оборвалась по-настоящему. Двое разбились. Отец потом каждый год пил за них на Покров, а за себя ни разу.", "kind": "old"}, {"md": "В школе есть Шмелёв из первого «Б», и Шмелёву очень нравится слово «Водяной». Он булькает мне вслед на каждой перемене и показывает руками, как я тону."}], "file": "T-03.md", "choices": [{"id": "A", "label": "Вмазать Шмелёву, и будь что будет", "fx": [["add", "ТЕЛ", 10], ["add", "ВОЛ", 5], ["add", "ЭМП", -5], ["set", "F_Т03", "ШРАМ"]], "outcomes": [{"to": "Т-04"}]}, {"id": "B", "label": "«Ну Водяной, и чё?» — сделать кличку своей", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["set", "F_Т03", "ВОДЯНОЙ"]], "outcomes": [{"to": "Т-04"}]}, {"id": "C", "label": "Найти деда в тельняшке, который меня вытащил", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["set", "F_Т03", "ЗАМЕТКА"]], "outcomes": [{"to": "Т-04"}]}, {"id": "D", "label": "Больше никогда не говорить про воду, ваще", "fx": [["add", "РАЗ", 5], ["add", "ЭМП", 5], ["set", "F_Т03", "ВОДОБОЯЗНЬ"]], "outcomes": [{"to": "Т-04"}]}], "after": {"A": [{"md": "Я бью Шмелёва в нос прямо у раздевалки, и мы катаемся по полу, пока нас не растаскивает физрук. У Шмелёва из носа кровь, у меня рассечена бровь об угол скамейки. Бровь зашивают в той же Второй городской, где мне шили ладонь, и врач, увидев маму, говорит: «Опять вы?»"}, {"md": "Шмелёв с тех пор зовёт меня по фамилии. Шрам над бровью останется на всю жизнь."}], "B": [{"md": "— Ну Водяной, и чё? — говорю я Шмелёву при всём классе и булькаю ему в ответ, громко, с пузырями, как утопленник в мультике. Класс ржёт. Шмелёв теряется, потому что ржут не надо мной."}, {"md": "Через неделю Водяным меня зовут даже девчонки, и мне это нравится. Кличка прилипнет надолго."}], "C": [{"md": "Я пишу фломастером на тетрадных листках: «ИЩУ ДЕДА В ТЕЛЬНЯШКЕ КОТОРЫЙ МЕНЯ СПАС». Мама вздыхает, но помогает расклеить их по столбам на Рудничном."}, {"md": "Деда никто не находит. Зато в октябре в газете «Кузбасс» выходит заметка на полколонки про мальчика, который ищет своего спасителя. Мама вырезает её ножницами и прячет в сервант."}], "D": [{"md": "Про воду я больше не говорю. В ванну захожу только с открытой дверью, а когда мама набирает воду, ухожу в комнату. Мама сначала злится, потом водит меня к психологу в поликлинику, потом перестаёт."}, {"md": "Шмелёву скоро надоедает булькать. Какой интерес дразнить того, кто не отвечает."}]}}, "Т-04": {"id": "Т-04", "title": "Рельсовая война", "date": "май 1998", "age": 9, "stage": "trunk", "photo": "bw", "photo_caption": "Сковородки. Прихожая, 1998", "photo_prompt": "old black-and-white amateur photo, 1998, first-person view of a narrow soviet apartment hallway with a tall stack of cast iron frying pans next to the coat rack, a baby stroller, worn linoleum, grain, white border", "text": [{"md": "Зарплату на шахте не дают седьмой месяц. В феврале родилась Сонька, красная и громкая, как пожарная машина, а в апреле отцу вместо денег выдали сорок чугунных сковородок. Они стоят в прихожей башней, и об неё все спотыкаются, кроме Соньки, которая пока не ходит."}, {"md": "По телевизору всё время говорят слово «бартер». Я сначала думал, что это фамилия какого-то министра."}, {"md": "В мае шахтёры садятся на рельсы. Под Анжеро-Судженском стоят поезда, по Транссибу ничего не ходит, у нас под Кемеровом на ветке тоже жгут костры. Отец приходит домой ночью, пахнет дымом и говорит маме:"}, {"md": "— Пока не отдадут, не встанем."}, {"md": "— А есть что будем? — спрашивает мама. — Сковородки?"}, {"md": "У Витьки свой план. На старой подстанции за гаражами, говорит он, валяется медный кабель, бесхозный, а приёмка на Шахтёров платит за медь живыми деньгами. А наша учительница Нина Петровна говорит, что задачу про два поезда в классе решил я один, и в субботу в городе олимпиада для младших классов."}, {"md": "Суббота одна, а дел на неё четыре."}, {"md": "Через три месяца грохнул дефолт, и сковородки оказались самой твёрдой валютой в доме. Мама потом шутила, что это единственная зарплата, которую не съела инфляция.", "kind": "old"}], "file": "T-04.md", "choices": [{"id": "A", "label": "На рельсы, к отцу", "fx": [["add", "ВОЛ", 5], ["add", "ТЕЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_Т04", "РЕЛЬСЫ"]], "outcomes": [{"to": "Т-05"}]}, {"id": "B", "label": "С мамой на рынок, продавать сковородки", "fx": [["add", "ЭМП", 5], ["add", "РАЗ", 5], ["add", "СВЯЗЬ_МАМА", 5], ["set", "F_Т04", "РЫНОК"]], "outcomes": [{"to": "Т-05"}]}, {"id": "C", "label": "С Витькой за кабелем", "fx": [["add", "ТЕЛ", 10], ["add", "ВОЛ", 5], ["add", "РАЗ", -5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т04", "ЦВЕТМЕТ"]], "outcomes": [{"to": "Т-05"}]}, {"id": "D", "label": "На олимпиаду с Ниной Петровной", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["set", "F_Т04", "ОЛИМПИАДА"]], "outcomes": [{"to": "Т-05"}]}], "after": {"A": [{"md": "Ночь у костра на насыпи я запомню на всю жизнь. Мужики стучат касками по рельсам, ровно, как часы, кто-то жарит сало на проволоке. Отец сажает меня рядом и даёт подержать свою каску, тяжёлую и тёплую изнутри."}, {"md": "Под утро он говорит мне, как взрослому: «Запомни, Андрюха. Просить бесполезно. Надо стоять». Через неделю половину долга отдают живыми деньгами. Сковородки так и остаются в прихожей."}], "B": [{"md": "На рынке у Центрального мы с мамой стоим с восьми утра до темноты. К обеду я понимаю, что бабки покупают у того, кого жалко, и начинаю врать, что это последние, а папа в шахте. Про шахту, кстати, правда."}, {"md": "Мама краснеет, но молчит. К вечеру мы продаём девять сковородок, и мама впервые за месяц смеётся."}], "C": [{"md": "Кабель мы с Витькой режем ножовкой два дня и сдаём на приёмке за сто сорок рублей. Это больше, чем мама получила за апрель. У приёмки нас видят старшие пацаны с Рудничного, хлопают Витьку по плечу и запоминают нас обоих."}, {"md": "Маме я отдаю семьдесят рублей и вру, что нашёл. Она долго смотрит на меня и ничего не спрашивает."}], "D": [{"md": "На олимпиаде во Дворце пионеров я решаю все задачи, кроме последней, про улитку на столбе, и занимаю третье место. Нина Петровна покупает мне эскимо и говорит, что у меня «голова»."}, {"md": "Грамоту мама вешает на кухне, рядом с календарём. Отец смотрит на неё и ничего не говорит, но потом я вижу, как он показывает её дяде Толе."}]}}, "Т-05": {"id": "Т-05", "title": "Коробка", "date": "август 2000", "age": 11, "stage": "trunk", "photo": "bw", "photo_caption": "Т. С. и В. П., Томь, 1981", "photo_prompt": "old black-and-white photo from 1981, two men on a river bank, an older man in glasses and a hat resembling a miner, a thin young man holding a briefcase, wide Siberian river behind, faded, cracked emulsion, handwritten note on the white border", "text": [{"md": "В августе по телевизору целыми днями показывают подводную лодку «Курск». Мама смотрит новости и плачет, отец выключает телевизор и уходит курить на балкон. Они думают, что страшнее, чем там, внизу, в темноте, ничего на свете нет. Я там был. Там тесно, но не страшно. Только говорить про это нельзя, это я уже понял, поэтому сижу и молчу."}, {"md": "Чтобы я не путался под ногами, мама отправляет меня разбирать сарай. Там лыжи без креплений, папины удочки, банки с гвоздями и коробка из-под югославских сапог, перемотанная синей изолентой. В коробке тетради в клеточку, исписанные формулами, одна фотография и конверт с сургучной печатью. На конверте написано «Коле». Коля — это папа."}, {"md": "На фотографии двое мужчин у реки. Один в очках и шляпе, похожий на папу, только старше. Второй молодой и худой, с портфелем. На обороте выцветшими чернилами: «Т. С. и В. П., Томь, 1981»."}, {"md": "Мама заглядывает в сарай, видит конверт и сразу его забирает. «Это папе, не трогай». Конверт уезжает в сервант, за хрусталь, туда, где лежат документы и деньги на чёрный день."}, {"md": "Ночью я не сплю и слышу стук, ровный, как метроном у нас на музыке. Откуда стучит, не понять, то ли в батарее, хотя летом их не топят, то ли у меня в голове.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Сапоги из этой коробки мама носила восемь зим. Югославия тогда ещё умела делать сапоги.", "kind": "old"}], "file": "T-05.md", "choices": [{"id": "A", "label": "Читать тетради, пока никто не видит", "fx": [["add", "РАЗ", 5], ["add", "ДАР", 5], ["set", "F_Т05", "ТЕТРАДИ"]], "outcomes": [{"to": "Т-06"}]}, {"id": "B", "label": "Спросить маму, кто второй на фото", "fx": [["add", "ЭМП", 10], ["set", "F_Т05", "ФОТО"]], "outcomes": [{"to": "Т-06"}]}, {"id": "C", "label": "Отнести коробку старьёвщику на Советский: он даёт картриджи к «Сеге»", "fx": [["add", "ВОЛ", 10], ["add", "РАЗ", 5], ["add", "ТЕЛ", -5], ["set", "F_Т05", "ПРОДАЛ"]], "outcomes": [{"to": "Т-06"}]}, {"id": "D", "label": "Отдать коробку отцу", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_Т05", "СОЖЖЕНО"]], "outcomes": [{"to": "Т-06"}]}], "after": {"A": [{"md": "Тетради я читаю в сарае с фонариком, три вечера подряд. Из всех формул я понимаю одну фразу, написанную на полях карандашом: «Наблюдатель не видит своей смерти. Проверено»."}, {"md": "Я переписываю её на последнюю страницу тетради по русскому. Коробку заматываю изолентой обратно, и никто ничего не замечает."}], "B": [{"md": "— Это дедов аспирант, — говорит мама, посмотрев на фото, и сразу его забирает. — Отца про деда не спрашивай. Дед свою работу любил больше, чем их с бабушкой. Отец ему этого так и не простил."}, {"md": "Фотография уезжает в сервант, к конверту. Мама закрывает стеклянную дверцу и стоит возле неё ещё минуту."}], "C": [{"md": "Старьёвщик на Советском даёт мне за коробку картридж «Mortal Kombat 3» и ещё полтинник сверху. Соглашается он подозрительно быстро, но мне одиннадцать, и подозревать я пока не умею."}, {"md": "Остаток лета я сижу перед «Сегой» и учусь делать фаталити за Саб-Зиро. Про коробку мама спрашивает только в сентябре. Я говорю, что выкинул её с мусором."}], "D": [{"md": "Отец берёт коробку молча и уносит в гараж. Я иду следом и смотрю, как он кидает тетради в буржуйку по одной, не глядя. На полу остаётся обгоревший листок с половиной какой-то формулы."}, {"md": "— Дед твой был умный, — говорит отец. — Слишком."}, {"md": "Он закрывает буржуйку, и домой мы идём вместе. Он кладёт мне руку на плечо, первый раз за это лето."}]}}, "Т-06": {"id": "Т-06", "title": "Бакенщик", "date": "июль 2002", "age": 13, "stage": "trunk", "photo": "color", "photo_caption": "Витька, Ника и я. Лето 2002", "photo_prompt": "glossy color film print from 2002 with orange date stamp, first-person view, a 14-year-old boy smoking and squinting, a 13-year-old girl with braces holding a Strugatsky paperback, black still pond on a river bank, a white snag in the water, washed-out summer colors", "text": [{"md": "В июле опять приезжает Ника, первый раз с девяносто шестого. Я её сначала не узнаю. У неё брекеты, в рюкзаке Стругацкие, и Витьку она называет «Виктор», отчего Витька бесится так, что у него краснеют уши. Витьке четырнадцать, он курит «Яву», понтуется и сплёвывает сквозь зубы, как дядя Толя-таксист."}, {"md": "Бублик теперь мой. Ника тогда, в девяносто шестом, уехала без него, сказала, что он «выбрал». Он вымахал в рыжего лопоухого кобеля, при виде Ники орёт дурниной и катается на спине. Ника делает вид, что ей всё равно, и чешет ему пузо минут десять.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "На третий день мы втроём идём на Чёрную заводь, никто никого не звал, просто ноги сами туда пошли. Заводь такая же чёрная, коряга на месте. Мне тринадцать, и я изо всех сил делаю вид, что мне плевать."}, {"md": "Я шесть лет не заходил в воду глубже колена. В ванной сижу только с открытой дверью. Витька про это знает и молчит, и за это я ему многое прощаю.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т03"}, "r": {"op": "lit", "v": "ВОДОБОЯЗНЬ"}}}, {"md": "— Ну чё, Водяной, — говорит Витька, — реванш?"}, {"md": "Ника молчит. Она смотрит на корягу, а я смотрю на неё и думаю, что она, наверное, до сих пор помнит, до скольки досчитала."}, {"md": "Вверх по реке, за поворотом, торчит будка старого бакенщика. Бакенов на Томи давно никто не ставит, а бакенщик живёт там всё равно. Говорят, ему лет сто, и он видит всё, что творится на воде."}], "file": "T-06.md", "choices": [{"id": "A", "label": "Переплыть заводь. Вместе с Никой", "fx": [["add", "ТЕЛ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_НИКА", 10], ["set", "F_Т06", "ПЕРЕПЛЫЛ"]], "outcomes": [{"to": "Т-07"}]}, {"id": "B", "label": "Отвести Нику в сторону и рассказать ей про темноту под водой", "fx": [["add", "ЭМП", 5], ["add", "ДАР", 5], ["add", "СВЯЗЬ_НИКА", 15], ["set", "F_Т06", "ТАЙНА_НИКИ"]], "outcomes": [{"to": "Т-07"}]}, {"id": "C", "label": "Поржать вместе с Витькой над «новосибирской»", "fx": [["add", "ТЕЛ", 10], ["add", "ВОЛ", 5], ["add", "ДАР", -5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["add", "СВЯЗЬ_НИКА", -10], ["set", "F_Т06", "ПАЦАНЫ"]], "outcomes": [{"to": "Т-07"}]}, {"id": "D", "label": "Сходить вверх по реке, к бакенщику", "fx": [["add", "РАЗ", 5], ["add", "ЭМП", 5], ["set", "F_Т06", "БАКЕНЩИК"]], "outcomes": [{"to": "Т-07"}]}], "after": {"A": [{"md": "Мы с Никой плывём к коряге рядом, она чуть впереди. Холодно так, что сводит челюсть. У коряги я хватаюсь за белый сук, и мне вдруг становится легко: вода как вода, ничего она мне не сделает."}, {"md": "Обратно мы плывём наперегонки. Ника выигрывает на полкорпуса и смеётся с брекетами, а Витька на берегу орёт, что мы оба больные."}, {"md": "Шесть лет я не заходил в воду глубже колена. Вечером я первый раз за шесть лет моюсь в ванной с закрытой дверью.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т03"}, "r": {"op": "lit", "v": "ВОДОБОЯЗНЬ"}}}], "B": [{"md": "Мы садимся на тёплый камень поодаль от Витьки, и я рассказываю ей про темноту под водой. Про голоса, про тесноту, про счёт. Говорю и жду, что она засмеётся."}, {"md": "Ника не смеётся."}, {"md": "— Я верю, — говорит она. — Я же считала."}, {"md": "Больше я об этом никому не рассказываю. Она тоже."}], "C": [{"md": "Мы с Витькой ржём над её брекетами и над тем, как она говорит «Виктор». Ника молчит, потом собирает рюкзак и уходит одна, не оглядываясь."}, {"md": "Через три дня она уезжает в Новосибирск раньше срока. Витька говорит «ну и пусть». А мне весь вечер погано, и я никак не могу понять почему."}], "D": [{"md": "Бакенщик сидит у будки и чинит сеть. На вид ему лет сто, руки у него синие от наколок. Он долго меня разглядывает и говорит:"}, {"md": "— Сюда каждый июль приезжает мужик городской, в костюме. Лет пятнадцать уже. До света стоит у заводи. Не рыбачит, смотрит. Пацан у него тут, говорят, утоп, в восемьдесят восьмом. Так и не нашли."}, {"md": "Он сплёвывает в воду и больше со мной не разговаривает. Я иду обратно и всю дорогу думаю про того пацана с Шахтёрской, про которого рассказывала бабка с первого этажа."}]}}, "Т-07": {"id": "Т-07", "title": "Лёд", "date": "декабрь 2003", "age": 14, "stage": "trunk", "photo": "color", "photo_caption": "«Девятка» дяди Толи. Зима 2003", "photo_prompt": "glossy color film print from 2003 with orange date stamp, night, first-person view through a frosted windshield of a VAZ-2109, a frozen wide river ahead lit by headlights, snow, steam, a boy's hand on the gear stick, orange street lamps far behind", "text": [{"md": "В декабре Витька угоняет у дяди Толи «девятку». Не насовсем, на вечер. Дядя Толя в запое, ключи висят в прихожей на гвоздике, а на том берегу в клубе дискотека, и там будут девчонки из сто десятой школы. По мосту ехать нельзя, там гаишники. Значит, по льду, напрямик."}, {"md": "— Лёд встал, — говорит Витька. — Мужики на «Ниве» вчера проезжали. Сам видел."}, {"md": "На улице минус тридцать один, а вчера было минус девять. «Девятка» заводится с третьего раза и дышит паром, как корова. Из магнитолы орёт «Руки вверх». Витька сидит за рулём в отцовской ушанке и пытается найти первую передачу."}, {"md": "Я стою у пассажирской двери. Дверь открыта, Витька ждёт."}, {"md": "В затылке у меня холодеет, хотя ветра нет. Перед глазами на секунду, как от вспышки, загорается зелёная подсветка приборки, только почему-то под водой, и рыжие Витькины волосы плавают вверх.", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 10}}}, {"md": "— Ну ты едешь или как? — орёт Витька. — Там щас медляки начнутся, а мы тут сопли морозим."}], "file": "T-07.md", "choices": [{"id": "A", "label": "Выдернуть ключи из замка", "fx": [["add", "ВОЛ", 10], ["add", "СВЯЗЬ_ВИТЬКА", -5], ["set", "F_Т07", "КЛЮЧИ"]], "outcomes": [{"to": "Т-08"}]}, {"id": "B", "label": "Сесть и ехать", "fx": [["add", "ТЕЛ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т07", "ЛЁД"]], "outcomes": [{"to": "Т-08"}]}, {"id": "C", "label": "Добежать до автомата и позвонить отцу", "fx": [["add", "РАЗ", 10], ["add", "ЭМП", 5], ["add", "ВОЛ", -5], ["add", "СВЯЗЬ_ВИТЬКА", -10], ["set", "F_Т07", "СДАЛ"]], "outcomes": [{"to": "Т-08"}]}, {"id": "D", "label": "Рассказать Витьке, что я сейчас увидел", "fx": [["add", "ДАР", 10], ["set", "F_Т07", "ВИДЕНИЕ"]], "outcomes": [{"to": "Т-08"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 10}}, "visible_src": "ДАР >= 10"}], "after": {"A": [{"md": "Я выдёргиваю ключи из замка и прячу в карман. Витька орёт, лезет драться, потом пинает колесо и уходит пешком, без шапки, в минус тридцать один."}, {"md": "Неделю он со мной не здоровается. На восьмой день приходит мириться с бутылкой «Балтики», одной на двоих."}], "B": [{"md": "Метров за двадцать до того берега «девятка» проваливается передом. Вода заливает ноги, Витька матерится, а я вдруг очень спокойно говорю ему: «В окно, быстро». Сам не знаю, откуда я знаю."}, {"md": "Мы вылезаем через окна, ползём по льду на животах и бежим домой в ледяной одежде, которая к подъезду стоит колом. «Девятку» вытаскивают трактором через три дня. Дядя Толя так и не узнаёт, что за рулём был Витька."}], "C": [{"md": "Я добегаю до автомата у магазина и звоню отцу. Он приезжает на попутке через пятнадцать минут и вынимает Витьку из машины за воротник."}, {"md": "Дядя Толя потом бьёт Витьку ремнём, и Витьку ставят на учёт в детской комнате милиции. Витька говорит мне только одно: «Ну ты и крыса, Андрюха»."}], "D": [{"md": "Я говорю Витьке, что сейчас видел: зелёную подсветку приборки под водой и его волосы. Говорю тихо и, видно, так, что Витька бледнеет и глушит мотор."}, {"md": "Мы сидим в остывающей машине минут десять и молчим. Потом он вылезает и говорит: «Ну тебя нафиг, Водяной», и мы идём домой пешком. Ключи он вешает обратно на гвоздик."}]}}, "Т-08": {"id": "Т-08", "title": "Везунчик", "date": "апрель 2005", "age": 16, "stage": "trunk", "photo": "color", "photo_caption": "АБК «Глубокой». Третьи сутки", "photo_prompt": "glossy color film print from 2005 with orange date stamp, first-person view, crowd of women in puffy winter jackets outside a coal mine administrative building at dawn, a handwritten list of names on a board, a TV crew with a camera, grey April slush", "text": [{"md": "В апреле на «Глубокой» взрывается метан. Под землёй остаются двенадцать человек, и отец среди них."}, {"md": "Трое суток весь Рудничный стоит у АБК. Женщины в пуховиках, на доске листок со списком, написанным от руки, прокурор, телевизионщики из Новосибирска, которые всё время спрашивают, «что вы сейчас чувствуете». Мама им не отвечает. Она стоит и держит Соньку за капюшон, чтобы та не убежала. Я стою рядом и каждый час пересчитываю фамилии в списке, их всё ещё двенадцать."}, {"md": "Бублик три ночи воет во дворе, и никто из соседей на него не ругается.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "В первые сутки поднимают шестерых, потом долго никого. На четвёртое утро клеть привозит ещё троих. Отец выходит вторым. Он серый, как штукатурка, и стреляет у кого-то сигарету, хотя всю жизнь курит только свои. Мама к нему не бежит. Она садится на корточки прямо в грязь и закрывает лицо руками."}, {"md": "Вечером, на кухне, когда мама с Сонькой уже спят, отец долго молчит, а потом говорит мне тихо:"}, {"md": "— Я там чуял, что умер, Андрюха. Три раза чуял. А потом стою у сбойки, живой, и дышу."}, {"md": "Бублик рычит на него из-под стола, первый и последний раз в жизни.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "Больше он про это не говорит ни тогда, ни потом."}, {"md": "Живыми из двенадцати подняли девятерых. Остальных троих отец потом поминал на каждый Покров, вместе с двумя из девяносто первого.", "kind": "old"}, {"md": "Меня потом часто спрашивали, где я был эти трое суток. Я всегда отвечал коротко."}], "file": "T-08.md", "choices": [{"id": "A", "label": "«Таскал баллоны горноспасателям». Пролез к ним в первую же ночь, и меня не выгнали", "fx": [["add", "ТЕЛ", 5], ["add", "ВОЛ", 5], ["set", "F_Т08", "ПАЛЫЧ"]], "outcomes": [{"to": "Т-09"}]}, {"id": "B", "label": "«Дома». Мама, Сонька, суп, и ни одной слезы при них", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_МАМА", 10], ["set", "F_Т08", "ДОМ"]], "outcomes": [{"to": "Т-09"}]}, {"id": "C", "label": "«На речке». Каждую ночь ходил на заводь разговаривать с водой", "fx": [["add", "ДАР", 5], ["add", "ЭМП", 5], ["set", "F_Т08", "ТОРГ"]], "outcomes": [{"to": "Т-09"}]}, {"id": "D", "label": "«Узнавал, почему рвануло». И всё рассказал журналистке из Новосибирска", "fx": [["add", "РАЗ", 10], ["add", "ВОЛ", 5], ["add", "ТЕЛ", -5], ["set", "F_Т08", "ДАТЧИКИ"]], "outcomes": [{"to": "Т-09"}]}], "after": {"A": [{"md": "Командир отделения горноспасателей, седой Палыч с голосом как из бочки, сначала гонит меня, а потом даёт таскать баллоны и воду. Трое суток я сплю урывками на лавке в их бытовке."}, {"md": "На третью ночь Палыч учит меня, куда бежать, если в штреке пошёл дым. «Против струи, понял? Всегда против струи». Я повторяю это про себя, пока не засыпаю."}], "B": [{"md": "Я варю суп из того, что есть в холодильнике, укладываю Соньку и вру ей, что папа на рыбалке. Мама три ночи сидит на кухне в пальто и не снимает его."}, {"md": "Я ни разу не плачу при них. Потом я очень этим гордился, хотя гордиться тут было нечем."}], "C": [{"md": "Каждую ночь я хожу к заводи и сижу на берегу. В воду не захожу, просто говорю с ней вслух, как дурак: «Возьми меня вместо»."}, {"md": "Вода молчит. На четвёртое утро, когда я возвращаюсь с реки, весь двор уже знает, что отца подняли."}], "D": [{"md": "В курилке у АБК я слышу, как мастер вполголоса говорит, что датчики метана на участке были заклеены, чтобы давать план. Я нахожу журналистку из Новосибирска и рассказываю ей всё."}, {"md": "Потом три дня лежу с температурой, потому что трое суток простоял на ветру. Сюжет выходит по телевизору, и фамилию «Самохин» запоминает директор шахты."}]}}, "Т-09": {"id": "Т-09", "title": "Проводы", "date": "июнь 2006", "age": 17, "stage": "trunk", "photo": "color", "photo_caption": "Проводы. Витька в центре", "photo_prompt": "glossy color film print from 2006 with orange date stamp, first-person view, a crowded courtyard farewell party for an army conscript, a shaved-head 18-year-old with a red face holding a glass, an accordion player, women crying, a table with salads in a soviet courtyard, evening light", "text": [{"md": "Витьке восемнадцать, и военкомат про него вспомнил. Повестка на двадцатое, служить два года, от звонка до звонка. Витька ходит по двору бритый наголо и делает вид, что ему смешно."}, {"md": "В ту же неделю приезжает Ника. У неё последнее лето перед одиннадцатым классом, и её отпустили к нам «в последний раз, потом поступать». Брекетов уже нет. Она подстриглась коротко, и на неё теперь оглядываются во дворе даже мужики у гаражей."}, {"md": "А Сварной, который держит приёмку металла на Шахтёров, а заодно половину Рудничного, говорит Витьке у ларька, что армию можно и «решить». Не бесплатно, конечно, «отдашь потом»."}, {"md": "Отец в эти дни приходит со смены и сразу уходит в гараж. Сидит там допоздна. Мама говорит: «Иди посиди с ним, он сам не позовёт»."}, {"md": "Проводы в субботу, Ника уезжает в воскресенье утром. Гараж, конечно, никуда не денется. Только батя сам не позовёт, тут мама права."}], "file": "T-09.md", "choices": [{"id": "A", "label": "Проводить Витьку как положено", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т09", "АРМИЯ"]], "outcomes": [{"to": "Т-10"}]}, {"id": "B", "label": "Помочь Витьке «решить» армию через Сварного", "fx": [["add", "ВОЛ", 5], ["add", "РАЗ", 5], ["add", "СВЯЗЬ_ВИТЬКА", 5], ["set", "F_Т09", "ДОЛГ_СВАРНОМУ"]], "outcomes": [{"to": "Т-10"}]}, {"id": "C", "label": "Уехать с Никой на дачу. Проводы как-нибудь без меня", "fx": [["add", "ЭМП", 10], ["add", "СВЯЗЬ_НИКА", 20], ["add", "СВЯЗЬ_ВИТЬКА", -10], ["set", "F_Т09", "НИКА"]], "outcomes": [{"to": "Т-10"}]}, {"id": "D", "label": "Пойти к отцу в гараж", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_Т09", "ДВЕРЬ"]], "outcomes": [{"to": "Т-10"}]}], "after": {"A": [{"md": "Проводы гуляем всем двором: гармонь, водка, Витькина мать воет в голос. Под утро Витька, пьяный и бритый, обнимает меня и говорит в ухо: «Ты это, мамку мою не бросай»."}, {"md": "Утром его увозит автобус от военкомата. Я машу, пока автобус не скрывается за поворотом."}], "B": [{"md": "Сварной решает армию за неделю: в военкомате у Витьки вдруг находят плоскостопие. Денег у нас нет, поэтому Сварной говорит: «Отработаете»."}, {"md": "Мы по очереди пожимаем ему руку. Ладонь у него мягкая и тёплая, и почему-то от этого страшнее всего."}], "C": [{"md": "Мы с Никой уезжаем на электричке на дачу её тётки и встречаем там рассвет. Что было на даче, пусть там и останется."}, {"md": "Утром я провожаю её на вокзал. Витькины проводы прошли без меня, и из армии он мне долго не пишет. Первое письмо приходит только через год."}], "D": [{"md": "Мы сидим с отцом в гараже до ночи. Он пьёт водку, я «Колокольчик». После второй бутылки отец вдруг говорит, глядя в стену:"}, {"md": "— Дед твой работал не на шахте. Под шахтой. Там была дверь."}, {"md": "Я жду, что он скажет дальше. Он молчит, долго, а потом говорит: «Иди спать»."}]}}, "Т-10": {"id": "Т-10", "title": "Рассвет", "date": "24 июня 2007, 04:12", "age": 18, "stage": "trunk", "photo": "digital", "photo_caption": "Выпускной. Набережная, 4 утра", "photo_prompt": "early digital camera photo from 2007, low resolution, first-person view, dawn over a wide Siberian river embankment, teenagers in suits and prom dresses with balloons, everyone holding up old Nokia phones, pale pink sky, a lone figure with a fishing rod on the far bank, slight motion blur", "text": [{"md": "Выпускной кончается на набережной, как у всех. Девчонки в платьях из «Ассорти», пацаны в пиджаках на вырост, шампанское «Советское» из горла, которое пронесли мимо классной в рукаве. Классная делает вид, что не видит, и сама то и дело лезет в сумочку за платком."}, {"md": "Галина Ивановна, наша астрономичка, ходит между нами в шали и раздаёт напутствия. Мне она говорит то же, что на последнем уроке говорила всему классу:"}, {"md": "— Комета Галлея вернётся двадцать восьмого июля шестьдесят первого. Вам будет по семьдесят два. Доживёте — посмотрите."}, {"md": "Все ржут. Семьдесят два — это никогда."}, {"md": "Витька тоже тут, хотя он из другого выпуска. Пришёл «проводить», в кожанке Сварного, и угощает всех «Парламентом». Мы с ним теперь должны Сварному на двоих, и это висит над нами, как туча над Кировским районом.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "ДОЛГ_СВАРНОМУ"}}}, {"md": "Витька служит под Читой. Месяц назад прислал письмо на полстраницы, из которых половину зачеркнул военный цензор, а может, сам Витька.", "if": {"op": "cmp", "c": "!=", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "ДОЛГ_СВАРНОМУ"}}}, {"md": "Небо над Томью розовеет. И тут у всего класса разом пищат «Нокии», у кого будильник, у кого эсэмэска «поздравляю». На моей «3310» четыре ноль-ноль. Я моргаю, и там уже четыре двенадцать. Моргаю ещё раз, а там всё равно четыре двенадцать."}, {"md": "Эсэмэска от Ники, из Новосибирска: «Не спишь? Я тоже. Смотрю на реку, у нас она другая». Я не отвечаю минут десять, потому что не знаю как.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "НИКА"}}}, {"md": "На том берегу кто-то стоит с удочкой, а может, это куст. Пока я присматриваюсь, с реки поднимается туман, и того берега становится не видно."}, {"md": "В восемнадцать самое время решать, кем быть, вот я и решил, во всех мирах по-разному. В каком-то, наверное, правильно. Знать бы ещё, в каком.", "kind": "old"}], "file": "T-10.md", "choices": [{"id": "A", "label": "«Как батя». Горный техникум и «Глубокая»", "fx": [["set", "F_ПУТЬ", "ЛАМПА"]], "outcomes": [{"to": "Д-00"}]}, {"id": "B", "label": "Поступать на физфак в Томск", "fx": [["set", "F_ПУТЬ", "ПРОТОКОЛ"]], "outcomes": [{"to": "В2-01"}], "visible": {"op": "or", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "РАЗ"}, "r": {"op": "num", "v": 40}}, {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}, {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т04"}, "r": {"op": "lit", "v": "ОЛИМПИАДА"}}]}, "visible_src": "РАЗ >= 40 || F_Т05 == ТЕТРАДИ || F_Т04 == ОЛИМПИАДА"}, {"id": "C", "label": "Рабочим в геологическую партию, в Горную Шорию", "fx": [["set", "F_ПУТЬ", "ПАРТИЯ"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "or", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 35}}, {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ВОЛ"}, "r": {"op": "num", "v": 40}}]}, "visible_src": "ТЕЛ >= 35 || ВОЛ >= 40"}, {"id": "D", "label": "Сварной звал: «Деньги нужны? Есть работа»", "fx": [["set", "F_ПУТЬ", "БАРАБАН"]], "outcomes": [{"to": "Ж-00"}]}, {"id": "E", "label": "Куда угодно, лишь бы отсюда", "fx": [["set", "F_ПУТЬ", "ТЁПЛАЯ_ВОДА"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ВОЛ"}, "r": {"op": "num", "v": 35}}, "visible_src": "ВОЛ >= 35"}, {"id": "F", "label": "Голоса в голове стали громче людей", "fx": [["set", "F_ПУТЬ", "ХОР"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 25}}, "visible_src": "ДАР >= 25"}, {"id": "G", "label": "Остаться. Работа, свадьба, дача. Просто жить", "fx": [["set", "F_ПУТЬ", "СЕМЬЯ"]], "outcomes": [{"to": "Ж-00"}]}]}}, "deaths": {"✝В2-02.A": {"id": "✝В2-02.A", "title": "Грузовой лифт", "date": "9 декабря 2008, 16:52", "age": 19, "stihia": "ВОЗДУХ", "epitaph": "19 лет. Главный корпус ТГУ, грузовой лифт между вторым и третьим. Ждал диспетчера.", "mourner": "Зоя Михайловна до пенсии водила студентов по лестнице, даже когда лифт починили.", "text": [{"md": "Я жму кнопку вызова. Динамик хрипит, женский голос говорит: «Мастер едет, ждите, не паникуйте». Я и не паникую, стою и жду, а туман поднимается мне до колен. Хочется сесть, и я сажусь, так удобнее. Последнее, что я успеваю заметить, это что мне совсем не страшно."}], "file": "X-B202A.md", "awake": [{"md": "…и лифт дёргается и встаёт между вторым и третьим. Лампочка мигает. Крышка сосуда шипит."}, {"md": "Я помню, как сидел на полу и мне было не страшно. Вот от этого меня сейчас и трясёт. Я умер и даже не заметил."}, {"md": "Туман снова ползёт по полу, низко, у самых кроссовок. Садиться мне больше не хочется."}]}, "✝В2-02.B": {"id": "✝В2-02.B", "title": "Грузовой лифт", "date": "9 декабря 2008, 16:44", "age": 19, "stihia": "ДОРОГА", "epitaph": "19 лет. Главный корпус ТГУ, шахта грузового лифта. Полез в щель.", "mourner": "Мама приехала за вещами и забрала из 412-й даже пустую банку из-под тушёнки.", "text": [{"md": "Я разжимаю створки руками, они поддаются со скрипом. Наверху щель в полметра, за ней пол третьего этажа и чьи-то ботинки. Я подтягиваюсь, пролезаю по пояс, и тут лифт, который, оказывается, никто не обесточил, вспоминает, что ему надо наверх."}, {"md": "Всё происходит быстро, больно только одну секунду."}], "file": "X-B202B.md", "awake": [{"md": "…и лифт дёргается и встаёт между вторым и третьим. Лампочка мигает. Крышка сосуда шипит."}, {"md": "Я хватаюсь за живот, потому что точно знаю, что его там нет. Живот на месте, свитер целый. Ботинки за щелью, кстати, были коричневые, это я откуда-то помню."}, {"md": "Туман ползёт по полу."}]}, "✝В2-02.C": {"id": "✝В2-02.C", "title": "Грузовой лифт", "date": "9 декабря 2008, 16:46", "age": 19, "stihia": "ХОЛОД", "epitaph": "19 лет. Главный корпус ТГУ, грузовой лифт. Открыл сосуд с азотом.", "mourner": "Дэн из Северска бросил физфак через месяц и уехал домой. Говорил, что из-за сессии.", "text": [{"md": "Я откручиваю крышку, чтобы сосуд перестал шипеть. Шипение и правда стихает, зато из горловины вываливается белое облако, плотное, как вата, и падает мне на руки. Руки сначала ничего не чувствуют, а потом я тоже ничего не чувствую, потому что облако заполняет кабину целиком."}], "file": "X-B202C.md", "awake": [{"md": "…и лифт дёргается и встаёт между вторым и третьим. Лампочка мигает. Крышка сосуда шипит."}, {"md": "Я смотрю на свои руки, розовые и тёплые. Минуту назад они были белые и не мои."}, {"md": "Я только что умер, вот в этом лифте. Стою, повторяю это про себя и не могу остановиться."}]}, "✝В2-03.A": {"id": "✝В2-03.A", "title": "Лагерный сад", "date": "14 января 2009, 03:40", "age": 19, "stihia": "ХОЛОД", "epitaph": "19 лет. Лагерный сад, лавочка у памятника. Присел отдохнуть.", "mourner": "Утром его нашёл дворник. Лена ещё долго говорила всем, что звала его остаться.", "text": [{"md": "Первые два километра я иду бодро и даже пою про себя «Выхода нет». На третьем перестаю чувствовать пальцы ног. В Лагерном саду лавочка у памятника вся в инее и почему-то кажется тёплой. Я сажусь на минутку, перевести дух. Звёзды над Томью крупные, и вставать мне больше не хочется."}], "file": "X-B203A.md", "awake": [{"md": "…и я стою у Лёхиного подъезда. Минус сорок два. Фонари в рыжем тумане."}, {"md": "Мне жарко, а ноги как чужие, хотя я ещё и шагу не сделал. Самое поганое, что лавочка была тёплая."}]}, "✝В2-03.C": {"id": "✝В2-03.C", "title": "Лагерный сад", "date": "14 января 2009, 03:50", "age": 19, "stihia": "ХОЛОД", "epitaph": "19 лет. Лагерный сад. Не понял, что его звали, и пошёл пешком.", "mourner": "Лена перевелась в Новосибирск и никогда больше не ходила на старый Новый год.", "text": [{"md": "Я говорю Лене что-то про холод и про то, что пора. Она говорит: «Ну давай». Что это значит, я не понимаю и иду пешком. Дальше по той же дорожке через Лагерный сад, пока не перестаю чувствовать пальцы, и до самой лавочки у памятника."}], "file": "X-B203C.md", "awake": [{"md": "…и я стою у Лёхиного подъезда. Лена ковыряет варежкой снег на перилах."}, {"md": "Она меня звала. Сейчас до меня это доходит так ясно, будто она сказала вслух. А тот я не понял и пошёл замерзать."}]}, "✝В2-08.A": {"id": "✝В2-08.A", "title": "Двенадцать минут", "date": "14 апреля 2016, 04:23", "age": 27, "stihia": "ХОЛОД", "epitaph": "27 лет. Шахта «Глубокая», горизонт минус шестьсот сорок. Сердце не запустилось.", "mourner": "Лунёв сам поднялся на-гора и сам пошёл к моей матери. Говорят, она его не ударила.", "text": [{"md": "Я остаюсь. Голоса становятся громче, а потом тише, и снаружи больше не пищит. Там тянется ровный звук, как гудок в трубке, когда на том конце бросили. Лунёв давит мне на грудь обеими руками и считает вслух. Этот счёт я узнаю, только в этот раз до двухсот пятидесяти двух он не доходит."}], "file": "X-B208A.md", "awake": [{"md": "…и монитор снаружи пищит неправильно. Девятая минута."}, {"md": "Я помню ровный гудок. Помню, как Лунёв перестал считать. Холод сейчас такой же, и голоса так же зовут. Одного раза дослушать мне хватило."}]}, "✝В2-08.C": {"id": "✝В2-08.C", "title": "Двенадцать минут", "date": "14 апреля 2016, 04:21", "age": 27, "stihia": "ВОДА", "epitaph": "27 лет. Горизонт минус шестьсот сорок. Ушёл за детским голосом и не нашёл дороги назад.", "mourner": "Ника долго не могла смотреть на воду. Даже из окна поезда.", "text": [{"md": "Я иду на детский голос, и темнота становится водой, чёрной, как заводь. Мальчик совсем близко, надо мной, на свету, мне видна его панамка с вишнями. Я плыву к нему, а он не приближается. Хор, оказывается, такой большой, что в нём можно заблудиться."}], "file": "X-B208C.md", "awake": [{"md": "…и монитор снаружи пищит неправильно. Девятая минута."}, {"md": "Я плыл за мальчиком и не догнал, хотя он всё время оставался на одном месте. Видно, к нему пока рано."}]}, "✝Д-01.A": {"id": "✝Д-01.A", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stihia": "ПОРОДА", "epitaph": "20 лет. Шахта «Глубокая», лава 3. Бежал.", "mourner": "Таня-ламповщица утром долго смотрела на пустой крючок с его номером.", "text": [{"md": "Я бегу. Шорох за спиной превращается в рёв, и меня бьёт в спину чёрной волной, тяжёлой, как мокрый цемент. Уголь течёт по-настоящему, как вода. Он заливает ноги, потом колени, потом грудь, и до меня доходит, что я тону, как тогда в заводи. Только эта вода наверх не пускает совсем."}, {"md": "Успеваю подумать: «Ну ёлки, опять». Потом пахнет мамиными волосами."}], "file": "X-D01A.md", "awake": [{"md": "…и я стою в забое. Пласт вздыхает. Михалыч замолкает на полуслове."}, {"md": "Пошевелиться я не могу. Я только что умер и помню, как уголь лез мне в рот. Минута, которой ещё не было, у меня уже позади."}, {"md": "Сердце колотится в рёбра, во рту сухо, и на зубах хрустит крошка. Михалыч смотрит на меня как на психа. Шорох впереди нарастает."}, {"md": "А за стенкой забоя, где нет ничего, кроме угля, плачет женщина."}]}, "✝Д-01.B": {"id": "✝Д-01.B", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stihia": "ПОРОДА", "epitaph": "20 лет. Шахта «Глубокая», лава 3. Лёг, как учили.", "mourner": "Отец поднялся на-гора последним и три дня ни с кем не разговаривал.", "text": [{"md": "Я падаю на почву лицом в мокрую крошку, руки на затылок, всё как учили на курсах. Уголь приходит сверху и прижимает к земле, спокойно и по-хозяйски, и становится тихо. Вдохнуть не могу, пальцем пошевелить не могу. Под щекой холодно, и я вспоминаю, что меня уже так держали, в тёплой темноте, где было тесно от голосов."}, {"md": "Голоса здесь, совсем рядом, и, похоже, мне рады."}], "file": "X-D01B.md", "awake": [{"md": "…и я стою в забое. Пласт вздыхает. Михалыч замолкает на полуслове."}, {"md": "Я только что лежал под углём и не мог вдохнуть. Сны так не болят. В ушах ещё звенит та тишина."}, {"md": "Шорох впереди нарастает, а я откуда-то точно знаю, что ложиться уже пробовал."}]}, "✝Д-01.C": {"id": "✝Д-01.C", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stihia": "ПОРОДА", "epitaph": "20 лет. Шахта «Глубокая», лава 3. Держался.", "mourner": "Мама полгода ставила на стол лишнюю тарелку и спохватывалась.", "text": [{"md": "Я обнимаю стойку крепи обеими руками, как в детстве мамину ногу в очереди за сахаром. Стойка вздрагивает, потом медленно гнётся и стонет. Я и не знал, что железо так умеет. Кровля садится на меня неторопливо, как старик на лавку. Последнее, что я вижу в свете лампы, это свои руки на стойке и шрам на ладони."}], "file": "X-D01C.md", "awake": [{"md": "…и я стою в забое. Пласт вздыхает. Михалыч замолкает на полуслове."}, {"md": "Смотрю на ладонь. Шрам на месте, руки целые. А плечи ещё помнят, как на них садилась кровля."}, {"md": "Я не псих. Я это знаю так же точно, как знаю, что сейчас пойдёт уголь."}]}, "✝Д-02.A": {"id": "✝Д-02.A", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stihia": "ВОЗДУХ", "epitaph": "23 года. Главный штрек, пятисотый метр. Бежал к стволу.", "mourner": "Серёга дошёл. Потом каждую годовщину пил и на восьмой рюмке называл его братом.", "text": [{"md": "Я бегу. Восемьсот метров для меня ерунда, наверху я пробегаю их за три минуты. Здесь воздуха становится всё меньше, сколько ни хватай его ртом. На четырёхсотом метре колени перестают слушаться. На пятисотом я обнаруживаю, что лежу, а как падал, не помню. Фонарь светит в кровлю. Очень хочется спать, и мама почему-то рассказывает про свои волосы, которые пахнут углём…"}], "file": "X-D02A.md", "awake": [{"md": "…и я стою в лаве. Датчик пищит. Серёга матерится в сорока метрах позади."}, {"md": "Лёгкие ещё горят, а щека помнит холодную почву на пятисотом метре и луч фонаря в кровле. Восемьсот метров для меня, выходит, много."}]}, "✝Д-02.B": {"id": "✝Д-02.B", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stihia": "ВОЗДУХ", "epitaph": "23 года. Старая сбойка. Сделал всё по инструкции, только по чужой.", "mourner": "Нашли через двое суток. Мама опознала его по шраму на ладони.", "text": [{"md": "Самоспасатель шипит, во рту резиновый привкус. Я сижу в сбойке и жду, как положено. Только сбойка тупиковая. Воздух в ней стоит, как в трёхлитровой банке, и газ натекает сюда первым, тихо, как кот на кухню. Доходит до меня это, только когда руки перестают слушаться и самоспасатель начинает казаться лишним и тяжёлым."}, {"md": "Я его снимаю. Мне вдруг хорошо и спокойно, и это последнее, что я думаю."}], "file": "X-D02B.md", "awake": [{"md": "…и я стою в лаве. Датчик пищит."}, {"md": "Сбойка была тупиковая. Кто учил инструкции, тот бы знал. А я сидел и ждал по правилам, пока меня отравят."}]}, "✝Д-02.C": {"id": "✝Д-02.C", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stihia": "ВОЗДУХ", "epitaph": "23 года. Лава 5. Вернулся за напарником.", "mourner": "Серёгу вытащили живым. Через год он назвал сына его именем.", "text": [{"md": "Я иду назад на его фонарь. Серёга сидит у конвейера и держится за ногу. Подвернул, когда прыгал через став. Я подставляю плечо. Мы идём, и он тяжёлый, как мешок с углём, и с каждым шагом тяжелее. Я его не роняю, просто в какой-то момент ложусь рядом, потому что кончился воздух."}], "file": "X-D02C.md", "awake": [{"md": "…и я стою в лаве. Серёга матерится в сорока метрах позади."}, {"md": "Я его не донёс. Сил не хватило, и плечо до сих пор чувствует, сколько он весит."}]}}};
